INSERT INTO moves
    (id, name, ko_name, type, power, accuracy, pp, category, priority, target, meta_category, ailment, ailment_chance, crit_rate, drain, healing, flinch_chance, stat_chance, min_hits, max_hits, is_contact, is_punch, is_bite, is_sound, is_powder, is_bullet, is_wind, is_slicing, is_dance, is_pulse, is_gravity, is_press, description, effect)
VALUES
    (7, 'fire-punch', '불꽃펀치', 'fire', 75, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'burn', 10, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '불꽃을 담은 펀치로 상대를 공격한다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (8, 'ice-punch', '냉동펀치', 'ice', 75, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'freeze', 10, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '냉기를 담은 펀치로 상대를 공격한다. 얼음 상태로 만들 때가 있다.', 'Has a chance to freeze the target.'),
    (9, 'thunder-punch', '번개펀치', 'electric', 75, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 10, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '전격을 담은 펀치로 상대를 공격한다. 마비 상태로 만들 때가 있다.', 'Has a chance to paralyze the target.'),
    (12, 'guillotine', '가위자르기', 'normal', NULL, 30, 5, 'physical', 0, 'selected-pokemon', 'ohko', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '큰 집게로 상대를 베어 갈라 공격한다. 맞으면 일격에 기절한다.', 'Causes a one-hit KO.'),
    (14, 'swords-dance', '칼춤', 'normal', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, true, false, false, false, '싸움의 춤을 격렬하게 춰서 기세를 높인다. 자신의 공격을 크게 올린다.', 'Raises the user’s Attack by two stages.'),
    (18, 'whirlwind', '날려버리기', 'normal', NULL, NULL, 20, 'status',  -6, 'selected-pokemon', 'force-switch', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, '상대를 날려버려서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', 'Immediately ends wild battles.  Forces trainers to switch Pokémon.'),
    (19, 'fly', '공중날기', 'flying', 90, 95, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, true, false, '1턴째에 하늘을 날아 2턴째에 상대를 공격한다.', 'User flies high into the air, dodging all attacks, and hits next turn.'),
