    (114, 'haze', '흑안개', 'ice', NULL, NULL, 30, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '흑안개를 뿜어 배틀에 참가 중인 포켓몬 전원의 능력 변화를 원래대로 돌린다.', 'Resets all Pokémon’s stats, accuracy, and evasion.'),
    (115, 'reflect', '리플렉터', 'psychic', NULL, NULL, 20, 'status', 0, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 이상한 장막을 쳐서 상대로부터 받는 물리공격의 데미지를 약하게 한다.', 'Reduces damage from physical attacks by half.'),
    (116, 'focus-energy', '기충전', 'normal', NULL, NULL, 30, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '깊게 숨을 들이마셔 기합을 넣는다. 자신의 공격이 급소에 맞기 쉬워진다.', 'Increases the user’s chance to score a critical hit.'),
    (120, 'self-destruct', '자폭', 'normal', 200, 100, 5, 'physical', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '폭발을 일으켜서 자신의 주위에 있는 포켓몬을 공격한다. 쓰고 나서 기절하게 된다.', 'User faints.'),
    (126, 'fire-blast', '불대문자', 'fire', 110, 85, 5, 'special', 0, 'selected-pokemon', 'damage-ailment', 'burn', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '큰 대자의 불꽃으로 상대를 불태운다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (127, 'waterfall', '폭포오르기', 'water', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 20, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '굉장한 기세로 상대에게 돌진한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (133, 'amnesia', '망각술', 'psychic', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '머리를 비워서 순간적으로 무언가를 잊어버림으로써 자신의 특수방어를 크게 올린다.', 'Raises the user’s Special Defense by two stages.'),
    (136, 'high-jump-kick', '무릎차기', 'fighting', 130, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, true, false, '점프해서 무릎차기로 상대를 공격한다. 빗나가면 자신이 데미지를 입는다.', 'If the user misses, it takes half the damage it would have inflicted in recoil.'),
    (137, 'glare', '뱀눈초리', 'normal', NULL, 100, 30, 'status', 0, 'selected-pokemon', 'ailment', 'paralysis', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '배의 무늬로 겁을 주어 상대를 마비 상태로 만든다.', 'Paralyzes the target.'),
    (141, 'leech-life', '흡혈', 'bug', 80, 100, 10, 'physical', 0, 'selected-pokemon', 'damage-heal', NULL, 0, 0, 50, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '피를 빨아서 상대를 공격한다. 준 데미지의 절반을 HP로 회복한다.', 'Drains half the damage inflicted to heal the user.'),
    (143, 'sky-attack', '불새', 'flying', 140, 90, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 1, 0, 0, 30, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '2턴째에 상대를 공격한다. 가끔 풀죽게 만든다. 급소에도 맞기 쉽다.', 'User charges for one turn before attacking.  Has a chance to make the target flinch.'),
    (144, 'transform', '변신', 'normal', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대 포켓몬으로 변신하여 상대와 완전히 똑같은 기술을 사용할 수 있다.', 'User becomes a copy of the target until it leaves battle.'),
    (151, 'acid-armor', '녹기', 'poison', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '세포의 변화로 액체가 되어 자신의 방어를 크게 올린다.', 'Raises the user’s Defense by two stages.'),
    (152, 'crabhammer', '집게해머', 'water', 100, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 1, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '큰 집게를 상대에게 내리쳐서 공격한다. 급소에 맞기 쉽다.', 'Has an increased chance for a critical hit.'),
    (153, 'explosion', '대폭발', 'normal', 250, 100, 5, 'physical', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '큰 폭발로 자신의 주위에 있는 포켓몬을 공격한다. 쓰고 나서는 기절한다.', 'User faints.'),
    (156, 'rest', '잠자기', 'psychic', NULL, NULL, 5, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '2턴 동안 계속 잠잔다. 자신의 HP와 상태 이상을 모두 회복한다.', 'User sleeps for two turns, completely healing itself.'),
    (157, 'rock-slide', '스톤샤워', 'rock', 75, 90, 10, 'physical', 0, 'all-opponents', 'damage', NULL, 0, 0, 0, 0, 30, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '큰 바위를 세차게 부딪쳐서 공격한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (161, 'tri-attack', '트라이어택', 'normal', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'unknown', 20, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '3개의 광선으로 공격한다. 마비, 화상 또는 얼음 상태 중 어느 하나로 만들 때가 있다.', 'Has a chance to burn, freeze, or paralyze the target.'),
    (162, 'super-fang', '분노의앞니', 'normal', NULL, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '날카로운 앞니로 강하게 물어서 공격한다. 상대의 HP는 절반이 된다.', 'Inflicts damage equal to half the target’s HP.'),
    (164, 'substitute', '대타출동', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 HP를 조금 깎아서 분신을 만든다. 분신은 자신의 대타가 된다.', 'Transfers 1/4 of the user’s max HP into a doll, protecting the user from further damage or status changes until it breaks.'),
    (165, 'struggle', '발버둥', 'normal', 50, NULL, 1, 'physical', 0, 'random-opponent', 'damage', NULL, 0, 0, 0,  -25, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '자신의 PP가 떨어지면 발버둥 쳐 상대를 공격한다. 자신도 조금 데미지를 입는다.', 'User takes 1/4 its max HP in recoil.'),
    (168, 'thief', '도둑질', 'dark', 60, 100, 25, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '공격과 동시에 도구를 훔친다. 자신이 도구를 지니고 있을 경우에는 훔칠 수 없다.', 'Takes the target’s item.'),
    (173, 'snore', '코골기', 'normal', 50, 100, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 30, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '자신이 잠들어 있을 때 소음을 내어 공격한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.  Only works if the user is sleeping.'),
    (174, 'curse', '저주', 'ghost', NULL, NULL, 10, 'status', 0, 'specific-move', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '기술을 쓰는 포켓몬이 고스트타입일 때와 그 이외의 타입일 때는 효과가 다르다.', 'Ghosts pay half their max HP to hurt the target every turn.  Others decrease Speed but raise Attack and Defense.'),
    (175, 'flail', '바둥바둥', 'normal', NULL, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '바둥바둥 난동 부려서 공격한다. 자신의 HP가 적을수록 기술의 위력이 올라간다.', 'Inflicts more damage when the user has less HP remaining, with a maximum of 200 power.'),
    (178, 'cotton-spore', '목화포자', 'grass', NULL, 100, 40, 'status', 0, 'all-opponents', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, true, false, false, false, false, false, false, false, '솜처럼 폭신폭신한 포자를 착 달라붙게 해서 상대의 스피드를 크게 떨어뜨린다.', 'Lowers the target’s Speed by two stages.'),
    (179, 'reversal', '기사회생', 'fighting', NULL, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '힘을 쥐어짜서 공격한다. 자신의 HP가 적을수록 기술의 위력이 올라간다.', 'Inflicts more damage when the user has less HP remaining, with a maximum of 200 power.'),
    (180, 'spite', '원한', 'ghost', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대가 마지막으로 사용한 기술에 원한을 품어 그 기술의 PP를 4만큼 줄인다.', 'Lowers the PP of the target’s last used move by 4.'),
    (182, 'protect', '방어', 'normal', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다.', 'Prevents any moves from hitting the user this turn.'),
    (183, 'mach-punch', '마하펀치', 'fighting', 40, 100, 30, 'physical', 1, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '눈에 보이지 않는 굉장한 속도로 펀치를 날린다. 반드시 선제공격을 할 수 있다.', 'Inflicts regular damage with no additional effect.'),
    (184, 'scary-face', '겁나는얼굴', 'normal', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '무서운 얼굴로 노려보고 겁주어 상대의 스피드를 크게 떨어뜨린다.', 'Lowers the target’s Speed by two stages.'),
    (186, 'sweet-kiss', '천사의키스', 'fairy', NULL, 75, 10, 'status', 0, 'selected-pokemon', 'ailment', 'confusion', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '천사처럼 귀엽게 키스하여 상대를 혼란시킨다.', 'Confuses the target.'),
    (187, 'belly-drum', '배북', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 HP를 최대 HP의 절반만큼 감소시켜 자신의 공격을 최대로 올린다.', 'User pays half its max HP to max out its Attack.'),
    (188, 'sludge-bomb', '오물폭탄', 'poison', 90, 100, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'poison', 30, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '더러운 오물을 상대에게 내던져서 공격한다. 독 상태로 만들 때가 있다.', 'Has a chance to poison the target.'),
