    (192, 'zap-cannon', '전자포', 'electric', 120, 50, 5, 'special', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '대포처럼 전기를 발사해서 공격한다. 상대를 마비 상태로 만든다.', 'Has a chance to paralyze the target.'),
    (194, 'destiny-bond', '길동무', 'ghost', NULL, NULL, 5, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '기술을 쓴 뒤 상대의 공격으로 기절했을 때 공격 상대도 기절하게 한다. 연속으로 쓰면 실패한다.', 'If the user faints this turn, the target automatically will, too.'),
    (195, 'perish-song', '멸망의노래', 'normal', NULL, NULL, 5, 'status', 0, 'all-pokemon', 'ailment', 'perish-song', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '노래를 들은 포켓몬은 3턴이 지나면 기절한다. 교체되면 효과가 없어진다.', 'User and target both faint after three turns.'),
    (196, 'icy-wind', '얼어붙은바람', 'ice', 55, 95, 15, 'special', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, '차가운 냉기를 상대에게 내뿜어 공격한다. 상대의 스피드를 떨어뜨린다.', 'Has a chance to lower the target’s Speed by one stage.'),
    (197, 'detect', '판별', 'fighting', NULL, NULL, 5, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 공격을 전혀 받지 않는다. 연속으로 쓰면 실패하기 쉽다.', 'Prevents any moves from hitting the user this turn.'),
    (198, 'bone-rush', '본러시', 'ground', 25, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, false, false, false, false, false, false, false, '단단한 뼈로 상대를 세게 때려서 공격한다. 2-5회 동안 연속으로 쓴다.', 'Hits 2-5 times in one turn.'),
    (199, 'lock-on', '록온', 'normal', NULL, NULL, 5, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '조준을 잘 맞춰 다음 공격이 반드시 상대에게 명중하도록 한다.', 'Ensures that the user’s next move will hit the target.'),
    (200, 'outrage', '역린', 'dragon', 120, 100, 10, 'physical', 0, 'random-opponent', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '2-3턴 동안 마구 난동 부려서 공격한다. 난동 부린 뒤에는 혼란에 빠진다.', 'Hits every turn for 2-3 turns, then confuses the user.'),
    (201, 'sandstorm', '모래바람', 'rock', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, '5턴 동안 모래바람을 일으켜 바위 땅, 강철타입 이외의 상대에게 데미지를 준다. 바위타입의 특수방어가 올라간다.', 'Changes the weather to a sandstorm for five turns.'),
    (202, 'giga-drain', '기가드레인', 'grass', 75, 100, 10, 'special', 0, 'selected-pokemon', 'damage-heal', NULL, 0, 0, 50, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '양분을 흡수하여 공격한다. 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', 'Drains half the damage inflicted to heal the user.'),
    (203, 'endure', '버티기', 'normal', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '공격을 받아도 HP를 반드시 1만큼은 남긴다. 연속으로 쓰면 실패하기 쉽다.', 'Prevents the user’s HP from lowering below 1 this turn.'),
    (204, 'charm', '애교부리기', 'fairy', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '귀엽게 바라보고 방심을 유도하여 상대의 공격을 크게 떨어뜨린다.', 'Lowers the target’s Attack by two stages.'),
    (207, 'swagger', '뽐내기', 'normal', NULL, 85, 15, 'status', 0, 'selected-pokemon', 'swagger', 'confusion', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대를 화내게 해서 혼란시킨다. 분노로 상대의 공격은 크게 올라가 버린다.', 'Raises the target’s Attack by two stages and confuses the target.'),
    (211, 'steel-wing', '강철날개', 'steel', 70, 90, 25, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 10, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '단단한 날개를 상대에게 부딪쳐서 공격한다. 자신의 방어가 올라갈 때가 있다.', 'Has a chance to raise the user’s Defense by one stage.'),
    (212, 'mean-look', '검은눈빛', 'normal', NULL, NULL, 5, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '빨려 들어갈 것 같은 까만 눈빛으로 가만히 응시하여 상대를 배틀에서 도망갈 수 없게 한다.', 'Prevents the target from leaving battle.'),
    (213, 'attract', '헤롱헤롱', 'normal', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'ailment', 'infatuation', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '수컷은 암컷을 암컷은 수컷을 유혹하여 헤롱헤롱하게 만든다. 상대가 기술을 쓰기 어려워진다.', 'Target falls in love if it has the opposite gender, and has a 50% chance to refuse attacking the user.'),
    (214, 'sleep-talk', '잠꼬대', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신이 배운 기술 중 하나를 무작위로 날린다. 자신이 잠들어 있을 때만 쓸 수 있다.', 'Randomly uses one of the user’s other three moves.  Only works if the user is sleeping.'),
    (215, 'heal-bell', '치료방울', 'normal', NULL, NULL, 5, 'status', 0, 'user-and-allies', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '기분 좋은 방울소리를 들려주어 같은 편 전원의 상태 이상을 회복한다.', 'Cures the entire party of major status effects.'),
    (219, 'safeguard', '신비의부적', 'normal', NULL, NULL, 25, 'status', 0, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 이상한 힘의 보호를 받아 상태 이상이 되지 않는다.', 'Protects the user’s field from major status ailments and confusion for five turns.'),
    (220, 'pain-split', '아픔나누기', 'normal', NULL, NULL, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 HP와 상대의 HP를 합친 것을 자신과 상대가 사이좋게 나눈다.', 'Sets the user’s and targets’s HP to the average of their current HP.'),
    (223, 'dynamic-punch', '폭발펀치', 'fighting', 100, 50, 5, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'confusion', 100, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '혼신의 힘으로 펀치를 날려서 공격한다. 상대를 반드시 혼란시킨다.', 'Has a chance to confuse the target.'),
    (224, 'megahorn', '메가혼', 'bug', 120, 85, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '단단하고 훌륭한 뿔로 마음껏 상대를 꿰찔러서 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (226, 'baton-pass', '배턴터치', 'normal', NULL, NULL, 40, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '교대 포켓몬과 바뀐다. 능력 변화는 바뀐 포켓몬이 그대로 이어받는다.', 'Allows the trainer to switch out the user and pass effects along to its replacement.'),
    (227, 'encore', '앙코르', 'normal', NULL, 100, 5, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대에게 앵콜시킨 기술을 3번 연속으로 쓰게 한다.', 'Forces the target to repeat its last used move every turn for 2 to 6 turns.'),
    (229, 'rapid-spin', '고속스핀', 'normal', 50, 100, 40, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '회전해서 상대를 공격한다. 조이기, 김밥말이, 씨뿌리기 등을 날려버린다. 자신의 스피드도 오른다.', 'Frees the user from binding moves, removes Leech Seed, and blows away Spikes.'),
    (230, 'sweet-scent', '달콤한향기', 'normal', NULL, 100, 20, 'status', 0, 'all-opponents', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '향기로 상대의 회피율을 크게 떨어뜨린다.', 'Lowers the target’s evasion by one stage.'),
    (231, 'iron-tail', '아이언테일', 'steel', 100, 75, 15, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 30, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '단단한 꼬리로 상대를 힘껏 쳐서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Defense by one stage.'),
    (234, 'morning-sun', '아침햇살', 'normal', NULL, NULL, 5, 'status', 0, 'user', 'heal', NULL, 0, 0, 0, 50, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 HP를 회복한다. 날씨에 따라 회복량이 변한다.', 'Heals the user by half its max HP.  Affected by weather.'),
    (235, 'synthesis', '광합성', 'grass', NULL, NULL, 5, 'status', 0, 'user', 'heal', NULL, 0, 0, 0, 50, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 HP를 회복한다. 날씨에 따라 회복량이 변한다.', 'Heals the user by half its max HP.  Affected by weather.'),
    (236, 'moonlight', '달빛', 'fairy', NULL, NULL, 5, 'status', 0, 'user', 'heal', NULL, 0, 0, 0, 50, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 HP를 회복한다. 날씨에 따라 회복량이 변한다.', 'Heals the user by half its max HP.  Affected by weather.'),
    (238, 'cross-chop', '크로스촙', 'fighting', 100, 80, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 1, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '양손으로 당수를 상대에게 힘껏 쳐서 공격한다. 급소에 맞기 쉽다.', 'Has an increased chance for a critical hit.'),
    (240, 'rain-dance', '비바라기', 'water', NULL, NULL, 5, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 비를 내리게 해서 물타입 기술의 위력을 올린다. 불꽃타입의 위력은 떨어진다.', 'Changes the weather to rain for five turns.'),
    (241, 'sunny-day', '쾌청', 'fire', NULL, NULL, 5, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 햇살을 강하게 해서 불꽃타입 기술의 위력을 올린다. 물타입의 위력은 떨어진다.', 'Changes the weather to sunny for five turns.'),
    (242, 'crunch', '깨물어부수기', 'dark', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 20, NULL, NULL, true, false, true, false, false, false, false, false, false, false, false, false, '날카로운 이빨로 상대를 깨물어 부숴서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Defense by one stage.'),
    (243, 'mirror-coat', '미러코트', 'psychic', NULL, 100, 20, 'special',  -5, 'specific-move', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대에게 받은 특수공격의 데미지를 2배로 만들어 그 상대에게 돌려준다.', 'Inflicts twice the damage the user received from the last special hit it took.'),
    (244, 'psych-up', '자기암시', 'normal', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신에게 암시를 걸어서 능력 변화 상태를 상대와 똑같은 상태로 만든다.', 'Discards the user’s stat changes and copies the target’s.'),
    (245, 'extreme-speed', '신속', 'normal', 80, 100, 5, 'physical', 2, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '눈에 보이지 않는 굉장한 속도로 상대에게 돌진하여 공격한다. 반드시 선제공격을 할 수 있다.', 'Inflicts regular damage with no additional effect.'),
    (246, 'ancient-power', '원시의힘', 'rock', 60, 100, 5, 'special', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 10, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '원시의 힘으로 공격한다. 자신의 모든 능력이 오를 때가 있다.', 'Has a chance to raise all of the user’s stats by one stage.'),
    (247, 'shadow-ball', '섀도볼', 'ghost', 80, 100, 15, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 20, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '까만 그림자의 덩어리를 내던져서 공격한다. 상대의 특수방어를 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Special Defense by one stage.'),
    (248, 'future-sight', '미래예지', 'psychic', 120, 100, 10, 'special', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '기술을 사용한 2턴 뒤에 상대에게 염동력의 덩어리를 보내어 공격한다.', 'Hits the target two turns later.'),
    (250, 'whirlpool', '바다회오리', 'water', 35, 85, 15, 'special', 0, 'selected-pokemon', 'damage-ailment', 'trap', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '세차게 소용돌이치는 물속에 4-5턴 동안 상대를 가두어 공격한다.', 'Prevents the target from leaving battle and inflicts 1/16 its max HP in damage for 2-5 turns.'),
    (251, 'beat-up', '집단구타', 'dark', NULL, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 6, 6, false, false, false, false, false, false, false, false, false, false, false, false, '같은 편 전원이 공격한다. 동료 포켓몬이 많을수록 기술의 공격 횟수가 증가한다.', 'Hits once for every conscious Pokémon the trainer has.'),
    (252, 'fake-out', '속이기', 'normal', 40, 100, 10, 'physical', 3, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 100, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '선제공격으로 상대를 풀죽게 한다. 배틀에 나가서 바로 쓰지 않으면 성공할 수 없다.', 'Can only be used as the first move after the user enters battle.  Causes the target to flinch.'),
    (253, 'uproar', '소란피기', 'normal', 90, 100, 10, 'special', 0, 'random-opponent', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '3턴 동안 소란 피워 공격한다. 그동안은 아무도 잠들지 않게 된다.', 'Forced to use this move for several turns.  Pokémon cannot fall asleep in that time.'),
    (254, 'stockpile', '비축하기', 'normal', NULL, NULL, 20, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '힘을 비축해서 자신의 방어와 특수방어를 올린다. 최대 3회까지 비축할 수 있다.', 'Stores energy up to three times for use with Spit Up and Swallow.'),
    (255, 'spit-up', '토해내기', 'normal', NULL, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '비축된 힘을 상대에게 부딪쳐서 공격한다. 비축된 만큼 위력이 올라간다.', 'Power is 100 times the amount of energy Stockpiled.'),
    (256, 'swallow', '꿀꺽', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'heal', NULL, 0, 0, 0, 25, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '비축된 힘을 꿀꺽해서 자신의 HP를 회복한다. 비축된 만큼 회복한다.', 'Recovers 1/4 HP after one Stockpile, 1/2 HP after two Stockpiles, or full HP after three Stockpiles.'),
    (257, 'heat-wave', '열풍', 'fire', 95, 90, 10, 'special', 0, 'all-opponents', 'damage-ailment', 'burn', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, '뜨거운 숨결을 상대에게 내뿜어 공격한다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (259, 'torment', '트집', 'dark', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'ailment', 'torment', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대에게 트집을 잡아서 똑같은 기술을 2회 연속으로 쓸 수 없게 한다.', 'Prevents the target from using the same move twice in a row.'),
    (260, 'flatter', '부추기기', 'dark', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'swagger', 'confusion', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대를 부추겨서 혼란시킨다. 동시에 상대의 특수공격도 올라가 버린다.', 'Raises the target’s Special Attack by one stage and confuses the target.'),
    (261, 'will-o-wisp', '도깨비불', 'fire', NULL, 85, 15, 'status', 0, 'selected-pokemon', 'ailment', 'burn', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '으스스하고 괴상한 불꽃을 쏘아 상대를 화상 상태로 만든다.', 'Burns the target.'),
    (262, 'memento', '추억의선물', 'dark', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신은 기절하게 되지만 그 대신 상대의 공격과 특수공격을 크게 떨어뜨린다.', 'Lowers the target’s Attack and Special Attack by two stages.  User faints.'),
    (263, 'facade', '객기', 'normal', 70, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '자신이 독, 마비, 화상 상태일 때 날리면 기술의 위력이 2배가 된다.', 'Power doubles if user is burned, paralyzed, or poisoned.'),
    (264, 'focus-punch', '힘껏펀치', 'fighting', 150, 100, 20, 'physical',  -3, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '정신력을 높여 펀치를 날린다. 기술을 쓰기 전에 공격을 받으면 실패한다.', 'If the user takes damage before attacking, the attack is canceled.'),
    (266, 'follow-me', '날따름', 'normal', NULL, NULL, 20, 'status', 2, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신에게 주목시켜 상대로부터의 공격을 모두 자신에게 향하게 한다.', 'Redirects the target’s single-target effects to the user for this turn.'),
    (268, 'charge', '충전', 'electric', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '다음 턴에 쓸 전기타입 기술의 위력을 올린다. 자신의 특수방어도 올라간다.', 'Raises the user’s Special Defense by one stage.  User’s Electric moves have doubled power next turn.'),
    (269, 'taunt', '도발', 'dark', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대를 화나게 한다. 3턴 동안 상대는 데미지를 주는 기술밖에 쓸 수 없게 된다.', 'For the next few turns, the target can only use damaging moves.'),
    (270, 'helping-hand', '도우미', 'normal', NULL, NULL, 20, 'status', 5, 'ally', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '동료를 돕는다. 도움받은 포켓몬이 쓰는 기술의 위력은 여느 때보다 커진다.', 'Ally’s next move inflicts half more damage.'),
    (271, 'trick', '트릭', 'psychic', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 빈틈을 노려 자신과 상대가 지닌 물건을 바꿔치기한다.', 'User and target swap items.'),
    (272, 'role-play', '역할', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 역할을 하여 자신도 상대와 같은 특성으로 변화한다.', 'Copies the target’s ability.'),
    (273, 'wish', '희망사항', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '다음 턴에 자신 또는 교체한 포켓몬의 HP를 최대 HP의 절반만큼 회복한다.', 'User will recover half its max HP at the end of the next turn.'),
    (275, 'ingrain', '뿌리박기', 'grass', NULL, NULL, 20, 'status', 0, 'user', 'ailment', 'ingrain', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '대지에 뿌리를 박아 매 턴마다 자신의 HP를 회복한다. 뿌리 박고 있으므로 교체할 수 없다.', 'Prevents the user from leaving battle.  User regains 1/16 of its max HP every turn.'),
    (276, 'superpower', '엄청난힘', 'fighting', 120, 100, 5, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '엄청난 힘을 발휘하여 상대를 공격한다. 자신의 공격과 방어가 떨어진다.', 'Lowers the user’s Attack and Defense by one stage after inflicting damage.'),
    (278, 'recycle', '리사이클', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '배틀 중에 사용하여 없어진 자신의 지닌 물건을 재생시켜 사용할 수 있게 한다.', 'User recovers the item it last used up.'),
    (280, 'brick-break', '깨트리기', 'fighting', 75, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '수도로 기세 좋게 내려쳐서 상대를 공격한다. 빛의장막이나 리플렉터 등도 파괴할 수 있다.', 'Destroys Reflect and Light Screen.'),
    (281, 'yawn', '하품', 'normal', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'ailment', 'yawn', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '큰 하품으로 졸음을 유도한다. 다음 턴에 상대를 잠듦 상태로 만든다.', 'Target sleeps at the end of the next turn.'),
    (282, 'knock-off', '탁쳐서떨구기', 'dark', 65, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '상대의 지닌 물건을 탁 쳐서 떨어뜨려 배틀이 끝날 때까지 사용할 수 없게 한다. 물건을 가진 상대에게는 데미지를 더 준다.', 'Target drops its held item.'),
    (283, 'endeavor', '죽기살기', 'normal', NULL, 100, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '상대의 HP가 자신의 HP와 같아지도록 데미지를 준다.', 'Lowers the target’s HP to equal the user’s.'),
    (284, 'eruption', '분화', 'fire', 150, 100, 5, 'special', 0, 'all-opponents', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '분노를 폭발시켜 상대를 공격한다. 자신의 HP가 적을수록 기술의 위력이 떨어진다.', 'Inflicts more damage when the user has more HP remaining, with a maximum of 150 power.'),
    (285, 'skill-swap', '스킬스왑', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '초능력으로 자신의 특성과 상대의 특성을 바꾼다.', 'User and target swap abilities.'),
    (286, 'imprison', '봉인', 'psychic', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대가 자신과 같은 기술을 배웠다면 상대만 그 기술을 사용할 수 없게 한다.', 'Prevents the target from using any moves that the user also knows.'),
    (291, 'dive', '다이빙', 'water', 80, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '1턴째에 잠수했다가 2턴째에 떠올라 공격한다.', 'User dives underwater, dodging all attacks, and hits next turn.'),
    (297, 'feather-dance', '깃털댄스', 'flying', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, true, false, false, false, '깃털을 흩뿌려 상대의 몸에 휘감는다. 상대의 공격을 크게 떨어뜨린다.', 'Lowers the target’s Attack by two stages.'),
    (298, 'teeter-dance', '흔들흔들댄스', 'normal', NULL, 100, 20, 'status', 0, 'all-other-pokemon', 'ailment', 'confusion', 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, true, false, false, false, '흔들흔들 댄스를 춰서 주위에 있는 포켓몬을 혼란 상태로 만든다.', 'Confuses the target.'),
    (299, 'blaze-kick', '블레이즈킥', 'fire', 85, 90, 10, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'burn', 10, 1, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '공격한 상대를 화상 상태로 만들 때가 있다. 급소에도 맞기 쉽다.', 'Has an increased chance for a critical hit and a chance to burn the target.'),
    (303, 'slack-off', '게으름피우기', 'normal', NULL, NULL, 5, 'status', 0, 'user', 'heal', NULL, 0, 0, 0, 50, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '게으름 피우며 쉰다. 자신의 HP를 최대 HP의 절반만큼 회복한다.', 'Heals the user by half its max HP.'),
    (304, 'hyper-voice', '하이퍼보이스', 'normal', 90, 100, 10, 'special', 0, 'all-opponents', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '시끄럽게 울리는 큰 진동을 상대에게 전달하여 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (305, 'poison-fang', '맹독엄니', 'poison', 50, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'poison', 50, 0, 0, 0, 0, 0, NULL, NULL, true, false, true, false, false, false, false, false, false, false, false, false, '독이 있는 이빨로 상대를 물어서 공격한다. 맹독을 주입할 때가 있다.', 'Has a chance to badly poison the target.'),
    (306, 'crush-claw', '브레이크클로', 'normal', 75, 95, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 50, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '단단하고 날카로운 손톱으로 베어 갈라서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Defense by one stage.'),
    (307, 'blast-burn', '블라스트번', 'fire', 150, 90, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '폭발하는 불꽃으로 상대를 태워서 공격한다. 다음 턴은 움직일 수 없다.', 'User foregoes its next turn to recharge.'),
    (308, 'hydro-cannon', '하이드로캐논', 'water', 150, 90, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '물의 대포를 상대에게 발사해서 공격한다. 다음 턴은 움직일 수 없다.', 'User foregoes its next turn to recharge.'),
    (309, 'meteor-mash', '코멧펀치', 'steel', 90, 90, 10, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 20, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '혜성과 같은 펀치를 날려서 상대를 공격한다. 자신의 공격이 올라갈 때가 있다.', 'Has a chance to raise the user’s Attack by one stage.'),
    (311, 'weather-ball', '웨더볼', 'normal', 50, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '사용했을 때의 날씨에 따라서 기술 타입과 위력이 바뀐다.', 'If there be weather, this move has doubled power and the weather’s type.'),
    (313, 'fake-tears', '거짓울음', 'dark', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '우는 척을 하며 눈물을 흘린다. 난처하게 만들어 상대의 특수방어를 크게 떨어뜨린다.', 'Lowers the target’s Special Defense by two stages.'),
    (314, 'air-cutter', '에어커터', 'flying', 60, 95, 25, 'special', 0, 'all-opponents', 'damage', NULL, 0, 1, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, true, false, false, false, false, '날카로운 바람으로 상대를 베어 공격한다. 급소에 맞기 쉽다.', 'Has an increased chance for a critical hit.'),
    (315, 'overheat', '오버히트', 'fire', 130, 90, 5, 'special', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '풀 파워로 상대를 공격한다. 쓰면 반동으로 자신의 특수공격이 크게 떨어진다.', 'Lowers the user’s Special Attack by two stages after inflicting damage.'),
    (317, 'rock-tomb', '암석봉인', 'rock', 60, 95, 15, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '암석을 내던져서 공격한다. 상대의 움직임을 봉인함으로써 스피드를 떨어뜨린다.', 'Has a chance to lower the target’s Speed by one stage.'),
    (319, 'metal-sound', '금속음', 'steel', NULL, 85, 40, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '금속을 긁을 때 나는 듯한 싫은 소리를 들려준다. 상대의 특수방어를 크게 떨어뜨린다.', 'Lowers the target’s Special Defense by two stages.'),
    (321, 'tickle', '간지르기', 'normal', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '몸을 간질여 웃게 만들어서 상대의 공격과 방어를 떨어뜨린다.', 'Lowers the target’s Attack and Defense by one stage.'),
    (322, 'cosmic-power', '코스믹파워', 'psychic', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '우주로부터 신비한 힘을 손에 넣음으로써 자신의 방어와 특수방어를 올린다.', 'Raises the user’s Defense and Special Defense by one stage.'),
    (323, 'water-spout', '해수스파우팅', 'water', 150, 100, 5, 'special', 0, 'all-opponents', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '바닷물을 내뿜어 공격한다. 자신의 HP가 적을수록 기술의 위력이 떨어진다.', 'Inflicts more damage when the user has more HP remaining, with a maximum of 150 power.'),
    (325, 'shadow-punch', '섀도펀치', 'ghost', 60, NULL, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '그림자에 섞여 펀치를 날린다. 공격은 반드시 명중한다.', 'Never misses.'),
    (326, 'extrasensory', '신통력', 'psychic', 80, 100, 20, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 10, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '보이지 않는 이상한 힘을 보내어 공격한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (328, 'sand-tomb', '모래지옥', 'ground', 35, 85, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'trap', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '세차게 불어대는 모래바람 속에 4-5턴 동안 상대를 가두어 공격한다.', 'Prevents the target from fleeing and inflicts damage for 2-5 turns.'),
    (329, 'sheer-cold', '절대영도', 'ice', NULL, 30, 5, 'special', 0, 'selected-pokemon', 'ohko', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대를 일격에 기절시킨다. 얼음타입 이외의 포켓몬이 사용하면 잘 맞지 않는다.', 'Causes a one-hit KO.'),
    (330, 'muddy-water', '탁류', 'water', 90, 85, 10, 'special', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 30, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '탁해진 물을 상대에게 발사하여 공격한다. 명중률을 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s accuracy by one stage.'),
    (331, 'bullet-seed', '씨기관총', 'grass', 25, 100, 30, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, true, false, false, false, false, false, false, '씨앗을 기세 좋게 상대에게 발사하여 공격한다. 2-5회 동안 연속으로 쓴다.', 'Hits 2-5 times in one turn.'),
    (332, 'aerial-ace', '제비반환', 'flying', 60, NULL, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '재빠른 움직임으로 상대를 농락해 벤다. 공격은 반드시 명중한다.', 'Never misses.'),
    (333, 'icicle-spear', '고드름침', 'ice', 25, 100, 30, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, false, false, false, false, false, false, false, '날카로운 고드름을 상대에게 발사하여 공격한다. 2-5회 동안 연속으로 쓴다.', 'Hits 2-5 times in one turn.'),
    (334, 'iron-defense', '철벽', 'steel', NULL, NULL, 15, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '피부를 쇠처럼 단단하게 만듦으로써 자신의 방어를 크게 올린다.', 'Raises the user’s Defense by two stages.'),
    (335, 'block', '블록', 'normal', NULL, NULL, 5, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '양팔을 벌려 막아서서 상대의 도주로를 가로막아 도망칠 수 없게 한다.', 'Prevents the target from leaving battle.'),
    (336, 'howl', '멀리짖기', 'normal', NULL, NULL, 40, 'status', 0, 'user-and-allies', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '큰 소리로 짖고 기합을 높여 자신과 같은 편의 공격을 올린다.', 'Raises the user’s Attack by one stage.'),
    (337, 'dragon-claw', '드래곤클로', 'dragon', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '날카롭고 뾰족한 거대한 발톱으로 상대를 베어 갈라서 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (338, 'frenzy-plant', '하드플랜트', 'grass', 150, 90, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '큰 나무로 상대를 힘껏 쳐서 공격한다. 다음 턴은 움직일 수 없게 된다.', 'User foregoes its next turn to recharge.'),
    (339, 'bulk-up', '벌크업', 'fighting', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '몸에 힘을 담아 근육을 두껍게 해서 자신의 공격과 방어를 올린다.', 'Raises the user’s Attack and Defense by one stage.'),
    (340, 'bounce', '뛰어오르기', 'flying', 85, 85, 5, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 30, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, true, false, '하늘 높이 뛰어올라 2턴째에 상대를 공격한다. 마비 상태로 만들 때가 있다.', 'User bounces high into the air, dodging all attacks, and hits next turn.'),
    (341, 'mud-shot', '머드샷', 'ground', 55, 95, 15, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '진흙 덩어리를 상대에게 내던져서 공격한다. 동시에 상대의 스피드를 떨어뜨린다.', 'Has a chance to lower the target’s Speed by one stage.'),
    (343, 'covet', '탐내다', 'normal', 60, 100, 25, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '귀엽게 애교 부리며 상대에게 다가가 지니고 있는 도구를 뺏는다.', 'Takes the target’s item.'),
    (344, 'volt-tackle', '볼트태클', 'electric', 120, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 10, 0,  -33, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '전기를 한데 모아 돌진한다. 자신도 상당한 데미지를 입는다. 마비 상태로 만들 때가 있다.', 'User takes 1/3 the damage inflicted in recoil.  Has a chance to paralyze the target.'),
    (347, 'calm-mind', '명상', 'psychic', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '조용히 정신을 통일하고 마음을 가라앉혀서 자신의 특수공격과 특수방어를 올린다.', 'Raises the user’s Special Attack and Special Defense by one stage.'),
    (348, 'leaf-blade', '리프블레이드', 'grass', 90, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 1, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '잎사귀를 칼처럼 이용해 상대를 베어 공격한다. 급소에 맞기 쉽다.', 'Has an increased chance for a critical hit.'),
    (349, 'dragon-dance', '용의춤', 'dragon', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, true, false, false, false, '신비롭고 힘센 춤을 격렬하게 춘다. 자신의 공격과 스피드를 올린다.', 'Raises the user’s Attack and Speed by one stage.'),
    (350, 'rock-blast', '록블라스트', 'rock', 25, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, true, false, false, false, false, false, false, '단단한 암석을 상대에게 발사하여 공격한다. 2-5회 동안 연속으로 쓴다.', 'Hits 2-5 times in one turn.'),
    (352, 'water-pulse', '물의파동', 'water', 60, 100, 20, 'special', 0, 'selected-pokemon', 'damage-ailment', 'confusion', 20, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, true, false, false, '물의 진동을 상대에게 가하여 공격한다. 상대를 혼란시킬 때가 있다.', 'Has a chance to confuse the target.'),
    (355, 'roost', '날개쉬기', 'flying', NULL, NULL, 5, 'status', 0, 'user', 'heal', NULL, 0, 0, 0, 50, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '땅에 내려와 몸을 쉬게 한다. 최대 HP의 절반만큼 HP를 회복한다.', 'Heals the user by half its max HP.'),
    (356, 'gravity', '중력', 'psychic', NULL, NULL, 5, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 부유나 비행타입에 땅타입의 기술이 맞게 된다. 공중으로 나는 기술도 사용할 수 없다.', 'Disables moves and immunities that involve flying or levitating for five turns.'),
    (359, 'hammer-arm', '암해머', 'fighting', 100, 90, 10, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '강하고 무거운 주먹을 휘둘러 데미지를 준다. 자신의 스피드가 떨어진다.', 'Lowers user’s Speed by one stage.'),
    (360, 'gyro-ball', '자이로볼', 'steel', NULL, 100, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, true, false, false, false, false, false, false, '몸을 고속으로 회전시켜 몸통박치기한다. 상대보다 스피드가 낮을수록 위력은 올라간다.', 'Power raises when the user has lower Speed, up to a maximum of 150.'),
    (361, 'healing-wish', '치유소원', 'psychic', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신은 기절하지만 교대하여 나오는 포켓몬의 상태 이상과 HP를 회복한다.', 'User faints.  Its replacement has its HP fully restored and any major status effect removed.'),
    (364, 'feint', '페인트', 'normal', 30, 100, 10, 'physical', 2, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '방어나 판별 등을 하고 있는 상대에게 공격할 수 있다. 방어 효과를 해제시킨다.', 'Hits through Protect and Detect.'),
    (365, 'pluck', '쪼아대기', 'flying', 60, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '부리로 공격한다. 상대가 나무열매를 지니고 있을 때 먹어서 나무열매의 효과를 받을 수 있다.', 'If target has a berry, inflicts double damage and uses the berry.'),
    (366, 'tailwind', '순풍', 'flying', NULL, NULL, 15, 'status', 0, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, '세차게 불어대는 바람의 소용돌이를 만들어 4턴 동안 같은 편 모두의 스피드를 올린다.', 'For three turns, friendly Pokémon have doubled Speed.'),
    (367, 'acupressure', '경혈찌르기', 'normal', NULL, NULL, 30, 'status', 0, 'user-or-ally', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '경혈을 눌러 몸을 활성화시킨다. 능력 중 하나를 크게 올린다.', 'Raises one of a friendly Pokémon’s stats at random by two stages.'),
    (368, 'metal-burst', '메탈버스트', 'steel', NULL, 100, 10, 'physical', 0, 'specific-move', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '기술을 쓰기 전에 마지막으로 받은 기술의 데미지를 늘려서 기술을 쓴 상대에게 돌려준다.', 'Strikes back at the last Pokémon to hit the user this turn with 1.5× the damage.'),
    (369, 'u-turn', '유턴', 'bug', 70, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '공격한 뒤 굉장한 스피드로 돌아와서 교대 포켓몬과 교체한다.', 'User must switch out after attacking.'),
    (370, 'close-combat', '인파이트', 'fighting', 120, 100, 5, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '방어를 포기하고 상대 쪽으로 깊숙이 돌격한다. 자신의 방어와 특수방어가 떨어진다.', 'Lowers the user’s Defense and Special Defense by one stage after inflicting damage.'),
    (371, 'payback', '보복', 'dark', 50, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '모아서 공격한다. 상대보다 나중에 공격할 수 있으면 기술의 위력은 2배가 된다.', 'Power is doubled if the target has already moved this turn.'),
    (372, 'assurance', '승부굳히기', 'dark', 60, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '그 턴에 상대가 이미 데미지를 입었다면 기술의 위력은 2배가 된다.', 'Power is doubled if the target has already received damage this turn.'),
    (374, 'fling', '내던지기', 'dark', NULL, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '지니게 한 도구를 재빠르게 내던져서 공격한다. 도구에 따라 위력과 효과가 바뀐다.', 'Throws held item at the target; power depends on the item.'),
    (379, 'power-trick', '파워트릭', 'psychic', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '초능력으로 자신의 공격과 방어의 힘을 교환한다.', 'User swaps Attack and Defense.'),
    (380, 'gastro-acid', '위액', 'poison', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 몸에 위액을 내뱉는다. 달라붙은 위액은 상대의 특성 효과를 지운다.', 'Nullifies target’s ability until it leaves battle.'),
    (383, 'copycat', '흉내쟁이', 'normal', NULL, NULL, 20, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '직전에 나온 기술을 흉내 내어 같은 기술을 쓴다. 기술이 나오지 않았으면 실패한다.', 'Uses the target’s last used move.'),
    (384, 'power-swap', '파워스왑', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '초능력으로 자신과 상대의 공격과 특수공격의 능력 변화를 교체한다.', 'User swaps Attack and Special Attack changes with the target.'),
    (385, 'guard-swap', '가드스왑', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '초능력으로 자신과 상대의 방어와 특수방어의 능력 변화를 교체한다.', 'User swaps Defense and Special Defense changes with the target.'),
    (387, 'last-resort', '비장의무기', 'normal', 140, 100, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '배틀 중에 기억하고 있는 기술을 모두 사용하면 그때부터 쓸 수 있는 필살기이다.', 'Can only be used after all of the user’s other moves have been used.'),
    (388, 'worry-seed', '고민씨', 'grass', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '마음을 괴롭히는 씨앗을 심는다. 상대를 잠잘 수 없게 해서 특성을 불면으로 만든다.', 'Changes the target’s ability to Insomnia.'),
    (389, 'sucker-punch', '기습', 'dark', 70, 100, 5, 'physical', 1, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '상대보다 먼저 공격할 수 있다. 상대가 쓴 기술이 공격기술이 아니면 실패한다.', 'Only works if the target is about to use a damaging move.'),
    (390, 'toxic-spikes', '독압정', 'poison', NULL, NULL, 20, 'status', 0, 'opponents-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 발밑에 독 압정을 뿌린다. 교체로 나온 상대 포켓몬에게 독을 퍼지게 한다.', 'Scatters poisoned spikes, poisoning opposing Pokémon that switch in.'),
    (392, 'aqua-ring', '아쿠아링', 'water', NULL, NULL, 20, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 몸 주변을 물로 만든 베일로 덮는다. 매 턴 HP를 회복한다.', 'Restores 1/16 of the user’s max HP each turn.'),
    (393, 'magnet-rise', '전자부유', 'electric', NULL, NULL, 10, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, true, false, '전기로 만든 자력의 힘으로 허공에 뜬다. 5턴 동안 부유할 수 있다.', 'User is immune to Ground moves and effects for five turns.'),
    (394, 'flare-blitz', '플레어드라이브', 'fire', 120, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'burn', 10, 0,  -33, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '불꽃을 두르고 돌진한다. 자신도 상당한 데미지를 입는다. 화상 상태로 만들 때가 있다.', 'User takes 1/3 the damage inflicted in recoil.  Has a chance to burn the target.'),
    (396, 'aura-sphere', '파동탄', 'fighting', 80, NULL, 20, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, true, false, false, '몸속에서 파동의 힘을 끌어내 상대에게 쏜다. 공격은 반드시 명중한다.', 'Never misses.'),
    (397, 'rock-polish', '록커트', 'rock', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 몸을 갈아 공기의 저항을 적게 한다. 스피드를 크게 올릴 수 있다.', 'Raises the user’s Speed by two stages.'),
    (398, 'poison-jab', '독찌르기', 'poison', 80, 100, 20, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'poison', 30, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '독에 물든 촉수나 팔로 상대를 꿰찌른다. 독 상태로 만들 때가 있다.', 'Has a chance to poison the target.'),
    (399, 'dark-pulse', '악의파동', 'dark', 80, 100, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 20, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, true, false, false, '몸에서 악의로 가득한 무서운 오라를 발한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (400, 'night-slash', '깜짝베기', 'dark', 70, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 1, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '순간적으로 틈을 노려 상대를 베어 버린다. 급소에 맞기 쉽다.', 'Has an increased chance for a critical hit.'),
    (401, 'aqua-tail', '아쿠아테일', 'water', 90, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '세차게 날뛰는 거친 파도와 같이 큰 꼬리를 흔들어서 상대를 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (402, 'seed-bomb', '씨폭탄', 'grass', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '단단한 껍질을 가지고 있는 큰 씨앗을 위에서 힘껏 내던져 상대를 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (403, 'air-slash', '에어슬래시', 'flying', 75, 95, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 30, 0, NULL, NULL, false, false, false, false, false, false, false, true, false, false, false, false, '하늘까지 베어 가르는 공기의 칼날로 공격한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (404, 'x-scissor', '시저크로스', 'bug', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '낫이나 발톱을 가위처럼 교차시키면서 상대를 베어 가른다.', 'Inflicts regular damage with no additional effect.'),
    (405, 'bug-buzz', '벌레의야단법석', 'bug', 90, 100, 10, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 10, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '진동으로 음파를 일으켜서 공격한다. 상대의 특수방어를 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Special Defense by one stage.'),
