    (408, 'power-gem', '파워젬', 'rock', 80, 100, 20, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '보석처럼 반짝이는 빛을 발사하여 상대를 공격한다.', 'Inflicts regular damage with no additional effect.'),
