    (415, 'switcheroo', '바꿔치기', 'dark', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '눈에 보이지 않는 속도로 자신과 상대가 지닌 물건을 교환한다.', 'User and target swap items.'),
