    (470, 'guard-split', '가드셰어', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '초능력으로 자신과 상대의 방어와 특수방어를 더해서 반으로 나눈다.', 'Averages Defense and Special Defense with the target.'),
    (471, 'power-split', '파워셰어', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '초능력으로 자신과 상대의 공격과 특수공격을 더해서 반으로 나눈다.', 'Averages Attack and Special Attack with the target.'),
    (472, 'wonder-room', '원더룸', 'psychic', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '이상한 공간을 만든다. 5턴 동안 모든 포켓몬의 방어와 특수방어가 바뀐다.', 'All Pokémon’s Defense and Special Defense are swapped for 5 turns.'),
    (473, 'psyshock', '사이코쇼크', 'psychic', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '이상한 염력파를 실체화하여 상대를 공격한다. 물리적인 데미지를 준다.', 'Inflicts damage based on the target’s Defense, not Special Defense.'),
    (474, 'venoshock', '베놈쇼크', 'poison', 65, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '특수한 독액을 끼얹는다. 독 상태의 상대에게는 위력이 2배가 된다.', 'Inflicts double damage if the target is Poisoned.'),
    (476, 'rage-powder', '분노가루', 'bug', NULL, NULL, 20, 'status', 2, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, true, false, false, false, false, false, false, false, '안절부절못하게 하는 가루를 자신에게 뿌려서 주의를 끈다. 상대의 공격은 모두 자신에게 향한다.', 'Redirects the target’s single-target effects to the user for this turn.'),
    (478, 'magic-room', '매직룸', 'psychic', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '이상한 공간을 만든다. 5턴 동안 모든 포켓몬의 도구의 효과가 사라진다.', 'Negates held items for five turns.'),
    (479, 'smack-down', '떨어뜨리기', 'rock', 50, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', 'unknown', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '돌이나 구슬을 던져서 날고 있는 상대를 공격한다. 맞은 상대는 땅에 떨어진다.', 'Removes any immunity to Ground damage.'),
    (480, 'storm-throw', '업어후리기', 'fighting', 60, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 6, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '강렬한 일격을 상대에게 날린다. 공격은 반드시 급소에 맞는다.', 'Always scores a critical hit.'),
    (482, 'sludge-wave', '오물웨이브', 'poison', 95, 100, 10, 'special', 0, 'all-other-pokemon', 'damage-ailment', 'poison', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '오물 파도로 자신의 주위에 있는 포켓몬을 공격한다. 독 상태로 만들 때가 있다.', 'Has a chance to poison the target.'),
    (483, 'quiver-dance', '나비춤', 'bug', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, true, false, false, false, '신비롭고 아름다운 춤을 경쾌하게 춘다. 자신의 특수공격과 특수방어와 스피드를 올린다.', 'Raises the user’s Special Attack, Special Defense, and Speed by one stage each.'),
    (484, 'heavy-slam', '헤비봄버', 'steel', NULL, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, true, '무거운 몸으로 상대에게 부딪쳐 공격한다. 자신이 상대보다 무거울수록 위력이 올라간다.', 'Power is higher when the user weighs more than the target, up to a maximum of 120.'),
    (486, 'electro-ball', '일렉트릭볼', 'electric', NULL, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '전기 덩어리를 상대에게 부딪쳐서 공격한다. 상대보다 스피드가 빠를수록 위력이 올라간다.', 'Power is higher when the user has greater Speed than the target, up to a maximum of 150.'),
    (487, 'soak', '물붓기', 'water', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '많은 물을 끼얹어서 상대를 물타입으로 바꾼다.', 'Changes the target’s type to Water.'),
    (488, 'flame-charge', '니트로차지', 'fire', 50, 100, 20, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '불꽃을 둘러 상대를 공격한다. 힘을 모아서 자신의 스피드를 올린다.', 'Inflicts regular damage.  Raises the user’s Speed by one stage.'),
    (489, 'coil', '똬리틀기', 'poison', NULL, NULL, 20, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '똬리를 틀어서 집중한다. 자신의 공격과 방어와 명중률을 올린다.', 'Raises the user’s Attack, Defense, and accuracy by one stage each.'),
    (490, 'low-sweep', '로킥', 'fighting', 65, 100, 20, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '재빠른 움직임으로 상대의 다리를 노려 공격한다. 상대의 스피드를 떨어뜨린다.', 'Lowers the target’s Speed by one stage.'),
    (491, 'acid-spray', '애시드봄', 'poison', 40, 100, 20, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '상대를 녹이는 액체를 토해내서 공격한다. 상대의 특수방어를 크게 떨어뜨린다.', 'Lowers the target’s Special Defense by two stages.'),
    (492, 'foul-play', '속임수', 'dark', 95, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '상대의 힘을 이용한다. 싸우고 있는 상대의 공격이 높을수록 데미지가 올라간다.', 'Calculates damage with the target’s attacking stat.'),
    (493, 'simple-beam', '심플빔', 'normal', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '수수께끼의 염력파를 상대에게 보낸다. 염력파를 받은 상대는 특성이 단순으로 바뀐다.', 'Changes the target’s ability to Simple.'),
    (494, 'entrainment', '동료만들기', 'normal', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '이상한 리듬으로 춤춘다. 움직임을 흉내 내게 해서 자신과 상대의 특성을 똑같게 만든다.', 'Copies the user’s ability onto the target.'),
    (495, 'after-you', '당신먼저', 'normal', NULL, NULL, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 행동을 도와서 자신이 행동한 뒤에 바로 움직일 수 있도록 한다.', 'Makes the target act next this turn.'),
    (496, 'round', '돌림노래', 'normal', 60, 100, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '노래로 상대를 공격한다. 함께 돌림노래를 하면 계속해서 쓸 수 있고 위력도 올라간다.', 'Has double power if it’s used more than once per turn.'),
    (499, 'clear-smog', '클리어스모그', 'poison', 50, NULL, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '특수한 진흙 덩어리를 상대에게 내던져서 공격한다. 능력 변화를 원래대로 돌린다.', 'Removes all of the target’s stat modifiers.'),
    (500, 'stored-power', '어시스트파워', 'psychic', 20, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '축적된 파워로 상대를 공격한다. 자신의 능력이 올라가 있는 만큼 위력이 오른다.', 'Power is higher the more the user’s stats have been raised, to a maximum of 31×.'),
    (501, 'quick-guard', '패스트가드', 'fighting', NULL, NULL, 15, 'status', 3, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신과 같은 편을 상대의 선제공격으로부터 지킨다.', 'Prevents any priority moves from hitting friendly Pokémon this turn.'),
    (502, 'ally-switch', '사이드체인지', 'psychic', NULL, NULL, 15, 'status', 2, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '이상한 힘으로 순간이동하여 자신과 같은 편의 위치를 바꾼다.', 'User switches places with the friendly Pokémon opposite it.'),
    (503, 'scald', '열탕', 'water', 80, 100, 15, 'special', 0, 'selected-pokemon', 'damage-ailment', 'burn', 30, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '뜨겁게 끓어오르는 물을 상대에게 발사해서 공격한다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (504, 'shell-smash', '껍질깨기', 'normal', NULL, NULL, 15, 'status', 0, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '껍질을 깨서 자신의 방어와 특수방어를 떨어뜨리지만 공격과 특수공격, 스피드를 크게 올린다.', 'Raises user’s Attack, Special Attack, and Speed by two stages.  Lower user’s Defense and Special Defense by one stage.'),
    (505, 'heal-pulse', '치유파동', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'heal', NULL, 0, 0, 0, 50, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, true, false, false, '치유파동을 날려서 최대 HP의 절반만큼 상대의 HP를 회복한다.', 'Heals the target for half its max HP.'),
    (506, 'hex', '병상첨병', 'ghost', 65, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '엎친 데 덮친 격으로 공격한다. 상태 이상인 상대에게 큰 데미지를 준다.', 'Has double power if the target has a major status ailment.'),
    (509, 'circle-throw', '배대뒤치기', 'fighting', 60, 90, 10, 'physical',  -6, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '상대를 내던져서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', 'Ends wild battles.  Forces trainers to switch Pokémon.'),
    (511, 'quash', '순서미루기', 'dark', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대를 억눌러서 행동의 순서를 마지막으로 만든다.', 'Makes the target act last this turn.'),
    (512, 'acrobatics', '애크러뱃', 'flying', 55, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '경쾌하게 상대를 공격한다. 자신이 도구를 지니고 있지 않을 때 큰 데미지를 준다.', 'Has double power if the user has no held item.'),
    (513, 'reflect-type', '미러타입', 'normal', NULL, NULL, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 타입을 반사해서 자신도 똑같은 타입이 된다.', 'User becomes the target’s type.'),
    (515, 'final-gambit', '목숨걸기', 'fighting', NULL, 100, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '목숨을 걸고 상대를 공격한다. 자신은 기절하게 되지만 상대에게 HP만큼의 데미지를 준다.', 'Inflicts damage equal to the user’s remaining HP.  User faints.'),
    (517, 'inferno', '연옥', 'fire', 100, 50, 5, 'special', 0, 'selected-pokemon', 'damage-ailment', 'burn', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '격렬한 불꽃으로 상대를 둘러싸 공격한다. 화상 상태로 만든다.', 'Has a chance to burn the target.'),
    (521, 'volt-switch', '볼트체인지', 'electric', 70, 100, 20, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '공격한 뒤 굉장한 스피드로 돌아와서 교대 포켓몬과 교체한다.', 'User must switch out after attacking.'),
    (522, 'struggle-bug', '벌레의저항', 'bug', 50, 100, 20, 'special', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '저항해서 상대를 공격한다. 상대의 특수공격을 떨어뜨린다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (523, 'bulldoze', '땅고르기', 'ground', 60, 100, 20, 'physical', 0, 'all-other-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '땅을 힘껏 밟아 자신의 주위에 있는 포켓몬을 공격한다. 상대의 스피드를 떨어뜨린다.', 'Has a chance to lower the target’s Speed by one stage.'),
    (524, 'frost-breath', '얼음숨결', 'ice', 60, 90, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 100, 6, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '차가운 숨결을 상대에게 내뿜어 공격한다. 반드시 급소에 맞는다.', 'Always scores a critical hit.'),
    (525, 'dragon-tail', '드래곤테일', 'dragon', 60, 90, 10, 'physical',  -6, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '상대를 튕겨내서 교대할 포켓몬을 끌어낸다. 야생의 경우에는 배틀이 끝난다.', 'Ends wild battles.  Forces trainers to switch Pokémon.'),
    (527, 'electroweb', '일렉트릭네트', 'electric', 55, 95, 15, 'special', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '전기 네트로 상대를 붙잡아서 공격한다. 상대의 스피드를 떨어뜨린다.', 'Lowers the target’s Speed by one stage.'),
    (528, 'wild-charge', '와일드볼트', 'electric', 90, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0,  -25, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '전기를 두르고 상대에게 부딪쳐 공격한다. 자신도 조금 데미지를 입는다.', 'User receives 1/4 the damage it inflicts in recoil.'),
    (529, 'drill-run', '드릴라이너', 'ground', 80, 95, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 1, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '드릴처럼 몸을 회전시켜서 상대에게 몸통박치기한다. 급소에 맞기 쉽다.', 'Has an increased chance for a critical hit.'),
    (532, 'horn-leech', '우드혼', 'grass', 75, 100, 10, 'physical', 0, 'selected-pokemon', 'damage-heal', NULL, 0, 0, 50, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '뿔을 꿰찔러서 상대의 양분을 흡수한다. 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', 'Drains half the damage inflicted to heal the user.'),
    (533, 'sacred-sword', '성스러운칼', 'fighting', 90, 100, 15, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '긴 뿔로 베어 공격한다. 상대의 능력 변화에 관계없이 데미지를 준다.', 'Ignores the target’s stat modifiers.'),
    (534, 'razor-shell', '셸블레이드', 'water', 75, 95, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 50, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '날카로운 조개껍질로 베어 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Defense by one stage.'),
    (535, 'heat-crash', '히트스탬프', 'fire', NULL, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, true, '불타는 몸으로 상대에게 부딪쳐서 공격한다. 자신이 상대보다 무거울수록 위력이 올라간다.', 'Power is higher when the user weighs more than the target, up to a maximum of 120.'),
    (538, 'cotton-guard', '코튼가드', 'grass', NULL, NULL, 10, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '푹신푹신한 솜털로 자신의 몸을 둘러싸서 지킨다. 방어를 매우 크게 올린다.', 'Raises the user’s Defense by three stages.'),
    (539, 'night-daze', '나이트버스트', 'dark', 85, 95, 10, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 40, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '암흑의 충격파를 날려서 상대를 공격한다. 명중률을 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s accuracy by one stage.'),
    (541, 'tail-slap', '스위프뺨치기', 'normal', 25, 85, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, true, false, false, false, false, false, false, false, false, false, false, false, '단단한 꼬리로 상대를 때려서 공격한다. 2-5회 동안 연속으로 쓴다.', 'Hits 2-5 times in one turn.'),
    (542, 'hurricane', '폭풍', 'flying', 110, 70, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'confusion', 30, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, '강렬한 바람으로 상대를 둘러싸서 공격한다. 상대를 혼란시킬 때가 있다.', 'Has a chance to confuse the target.'),
    (552, 'fiery-dance', '불꽃춤', 'fire', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 50, NULL, NULL, false, false, false, false, false, false, false, false, true, false, false, false, '불꽃을 두른 날개를 쳐서 공격한다. 자신의 특수공격이 오를 때가 있다.', 'Has a chance to raise the user’s Special Attack by one stage.'),
    (555, 'snarl', '바크아웃', 'dark', 55, 95, 15, 'special', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '호되게 호통을 쳐서 상대의 특수공격을 떨어뜨린다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (556, 'icicle-crash', '고드름떨구기', 'ice', 85, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 30, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '큰 고드름을 격렬하게 부딪쳐서 공격한다. 상대를 풀죽게 만들 때가 있다.', 'Has a chance to make the target flinch.'),
    (560, 'flying-press', '플라잉프레스', 'fighting', 100, 95, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, true, true, '공중에서 상대에게 다이브한다. 이 기술은 격투타입임과 동시에 비행타입이기도 하다.', 'Deals both Fighting and Flying-type damage.'),
    (562, 'belch', '트림', 'poison', 120, 90, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대를 향해 트림을 하여 데미지를 준다. 나무열매를 먹지 않으면 쓸 수 없다.', 'Can only be used after the user has eaten a berry.'),
    (564, 'sticky-web', '끈적끈적네트', 'bug', NULL, NULL, 20, 'status', 0, 'opponents-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 주위에 끈적끈적한 네트를 둘러 펼쳐 교체되어 나온 상대의 스피드를 떨어뜨린다.', 'Covers the opposing field, lowering opponents’ Speed by one stage upon switching in.'),
    (565, 'fell-stinger', '마지막일침', 'bug', 50, 100, 25, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '이 기술을 사용하여 상대를 쓰러뜨리면 공격이 매우 크게 오른다.', 'Raises the user’s Attack by two stages if it KOs the target.'),
    (566, 'phantom-force', '고스트다이브', 'ghost', 90, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '1턴째에 어디론가 사라져서 2턴째에 상대를 공격한다. 기술 방어를 무시하고 공격할 수 있다.', 'User vanishes, dodging all attacks, and hits next turn.  Hits through Protect and Detect.'),
    (567, 'trick-or-treat', '핼러윈', 'ghost', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대를 핼러윈으로 초대한다. 상대 타입에 고스트타입이 추가된다.', 'Adds Ghost to the target’s types.'),
    (568, 'noble-roar', '부르짖기', 'normal', NULL, 100, 30, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '우렁차게 부르짖어서 상대를 위협하여 상대의 공격과 특수공격을 떨어뜨린다.', 'Lowers the target’s Attack and Special Attack by one stage.'),
    (570, 'parabolic-charge', '파라볼라차지', 'electric', 65, 100, 20, 'special', 0, 'all-other-pokemon', 'damage-heal', NULL, 0, 0, 50, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '주위에 있는 모든 포켓몬에게 데미지를 준다. 준 데미지의 절반을 자신이 회복한다.', 'Heals the user for half the total damage dealt to all targets.'),
    (571, 'forests-curse', '숲의저주', 'grass', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대에게 숲의 저주를 건다. 저주에 걸린 상대는 타입에 풀타입이 추가된다.', 'Adds Grass to the target’s types.'),
    (572, 'petal-blizzard', '꽃보라', 'grass', 90, 100, 15, 'physical', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, true, false, false, false, false, false, '세찬 꽃보라를 일으켜서 주위에 있는 포켓몬을 공격하여 데미지를 준다.', 'Inflicts regular damage.'),
    (573, 'freeze-dry', '프리즈드라이', 'ice', 70, 100, 20, 'special', 0, 'selected-pokemon', 'damage-ailment', 'freeze', 10, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대를 급격히 차갑게 하여 얼음 상태로 만들 때가 있다. 물타입 포켓몬에게도 효과가 굉장해진다.', 'Super-effective against Water.'),
    (575, 'parting-shot', '막말내뱉기', 'dark', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '막말을 내뱉어 상대를 위협하여 공격과 특수공격을 떨어뜨린 후 교대 포켓몬과 교체한다.', 'Lowers all targets’ Attack and Special Attack by one stage.  Makes the user switch out.'),
    (576, 'topsy-turvy', '뒤집어엎기', 'dark', NULL, NULL, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대에게 걸려 있는 모든 능력 변화를 뒤집어서 반대로 만든다.', 'Inverts the target’s stat modifiers.'),
    (577, 'draining-kiss', '드레인키스', 'fairy', 50, 100, 10, 'special', 0, 'selected-pokemon', 'damage-heal', NULL, 0, 0, 75, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '키스로 상대의 HP를 흡수한다. 준 데미지의 반 이상 HP를 회복한다.', 'Drains 75% of the damage inflicted to heal the user.'),
    (580, 'grassy-terrain', '그래스필드', 'grass', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 그래스필드로 만든다. 땅에 있으면 매 턴 회복한다. 풀타입의 위력이 올라간다.', 'For five turns, heals all Pokémon on the ground for 1/16 max HP each turn and strengthens their Grass moves to 1.5× their power.'),
    (581, 'misty-terrain', '미스트필드', 'fairy', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 땅에 있으면 상태 이상이 되지 않고 드래곤타입 기술의 데미지도 절반이 된다.', 'For five turns, protects all Pokémon on the ground from major status ailments and confusion, and halves the power of incoming Dragon moves.'),
    (582, 'electrify', '송전', 'electric', NULL, NULL, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대가 기술을 쓰기 전에 송전하면 그 턴에 상대가 사용하는 기술은 전기타입이 된다.', 'Changes the target’s move’s type to Electric if it hasn’t moved yet this turn.'),
    (583, 'play-rough', '치근거리기', 'fairy', 90, 90, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 10, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '상대에게 치근거리며 공격한다. 상대의 공격을 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Attack by one stage.'),
    (585, 'moonblast', '문포스', 'fairy', 95, 100, 15, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 30, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '달의 파워를 빌려서 상대를 공격한다. 상대의 특수공격을 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (586, 'boomburst', '폭음파', 'normal', 140, 100, 10, 'special', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '무시무시한 폭음의 파괴력으로 주위에 있는 포켓몬을 공격한다.', 'Inflicts regular damage.'),
    (587, 'fairy-lock', '페어리록', 'fairy', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '록을 걸어 다음 턴의 모든 포켓몬을 도망가지 못하게 한다.', 'Prevents all Pokémon from fleeing or switching out during the next turn.'),
    (588, 'kings-shield', '킹실드', 'steel', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 공격을 막음과 동시에 방어 태세를 갖춘다. 접촉한 상대의 공격을 떨어뜨린다.', 'Blocks damaging attacks and lowers attacking Pokémon’s Attack by two stages on contact.  Switches Aegislash to Shield Forme.'),
    (594, 'water-shuriken', '물수리검', 'water', 15, 100, 20, 'special', 1, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, false, false, false, false, false, false, false, '점액으로 만든 수리검을 2-5회 동안 연속으로 던진다. 반드시 선제공격할 수 있다.', 'Hits 2–5 times.'),
    (595, 'mystical-fire', '매지컬플레임', 'fire', 75, 100, 10, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '입에서 내뱉는 아주 뜨거운 불꽃으로 공격한다. 상대의 특수공격을 떨어뜨린다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (596, 'spiky-shield', '니들가드', 'grass', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 공격을 막음과 동시에 접촉한 상대의 체력을 떨어뜨린다.', 'Blocks damaging attacks and damages attacking Pokémon for 1/8 their max HP.'),
    (597, 'aromatic-mist', '아로마미스트', 'fairy', NULL, NULL, 20, 'status', 0, 'ally', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '신비한 아로마 향으로 같은 편의 특수방어를 올린다.', 'Raises a selected ally’s Special Defense by one stage.'),
    (598, 'eerie-impulse', '괴전파', 'electric', NULL, 100, 15, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '몸에서 발생시킨 괴전파를 상대에게 쏘아 특수공격을 크게 떨어뜨린다.', 'Lowers the target’s Special Attack by two stages.'),
    (602, 'magnetic-flux', '자기장조작', 'electric', NULL, NULL, 20, 'status', 0, 'user-and-allies', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자기장 조작으로 인해 특성 플러스와 마이너스의 방어, 특수방어가 오른다.', 'Raises the Defense and Special Defense of all friendly Pokémon with Plus or Minus by one stage.'),
    (604, 'electric-terrain', '일렉트릭필드', 'electric', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 일렉트릭필드로 만든다. 땅에 있는 포켓몬은 잠들지 않는다. 전기타입의 위력이 올라간다.', 'For five turns, prevents all Pokémon on the ground from sleeping and strengthens their Electric moves to 1.5× their power.'),
    (605, 'dazzling-gleam', '매지컬샤인', 'fairy', 80, 100, 10, 'special', 0, 'all-opponents', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '강력한 빛을 내어 상대에게 데미지를 준다.', 'Inflicts regular damage with no additional effect.'),
    (608, 'baby-doll-eyes', '초롱초롱눈동자', 'fairy', NULL, 100, 30, 'status', 1, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '초롱초롱한 눈동자로 상대를 바라보며 공격을 떨어뜨린다. 반드시 선제공격할 수 있다.', 'Lowers the target’s Attack by one stage.'),
    (609, 'nuzzle', '볼부비부비', 'electric', 20, 100, 20, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'paralysis', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '전기가 흐르는 볼을 비벼서 공격한다. 상대를 마비 상태로 만든다.', 'Has a chance to paralyze the target.'),
    (611, 'infestation', '엉겨붙기', 'bug', 20, 100, 20, 'special', 0, 'selected-pokemon', 'damage-ailment', 'trap', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '4-5턴 동안 상대에게 엉겨 붙어서 공격한다. 그동안 상대는 도망갈 수 없다.', 'Prevents the target from fleeing and inflicts damage for 2-5 turns.'),
    (617, 'light-of-ruin', '파멸의빛', 'fairy', 140, 90, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0,  -50, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '영원의 꽃의 파워를 빌려서 강력한 광선을 쏜다. 자신도 상당한 데미지를 입는다.', 'User receives 1/2 the damage inflicted in recoil.'),
    (660, 'first-impression', '만나자마자', 'bug', 90, 100, 10, 'physical', 2, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '위력이 높은 기술이지만 배틀에 나가서 바로 쓰지 않으면 성공할 수 없다.', 'Can only be used as the first move after the user enters battle.'),
    (661, 'baneful-bunker', '토치카', 'poison', NULL, NULL, 10, 'status', 4, 'user', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 공격을 막음과 동시에 접촉한 상대에게 독을 퍼뜨린다.', 'Grants the user protection for the rest of the turn and poisons any Pokémon that tries to use a contact move on it.'),
    (662, 'spirit-shackle', '그림자꿰매기', 'ghost', 80, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '공격과 동시에 상대의 그림자를 꿰매 도망칠 수 없게 한다.', 'Traps the target.'),
    (663, 'darkest-lariat', 'DD래리어트', 'dark', 85, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '양팔을 돌려 상대에게 부딪친다. 상대의 능력 변화에 상관없이 데미지를 준다.', 'Ignores the target’s stat modifiers.'),
    (664, 'sparkling-aria', '물거품아리아', 'water', 90, 100, 10, 'special', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '노래 부르는 것으로 많은 벌룬을 방출한다. 기술에 맞으면 화상이 낫는다.', 'Cures the target of burns.'),
    (665, 'ice-hammer', '아이스해머', 'ice', 100, 90, 10, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '강하고 무거운 주먹을 휘둘러 데미지를 준다. 자신의 스피드가 떨어진다.', 'Lowers user’s Speed by one stage.'),
    (667, 'high-horsepower', '10만마력', 'ground', 95, 95, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '온몸을 써서 상대에게 맹렬히 어택한다.', 'Inflicts regular damage with no additional effect.'),
    (668, 'strength-sap', '힘흡수', 'grass', NULL, 100, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대 공격력과 동일하게 자신의 HP를 회복한다. 그리고 상대의 공격을 떨어뜨린다.', 'Heals the user by the target’s current Attack stat and lowers the target’s Attack by one stage.'),
    (669, 'solar-blade', '솔라블레이드', 'grass', 125, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '1턴째에 빛을 가득 모아 2턴째에 그 힘을 검에 담아 공격한다.', 'Requires a turn to charge before attacking.'),
    (672, 'toxic-thread', '독실', 'poison', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'swagger', 'poison', 100, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '독이 섞인 실을 뿜어낸다. 상대를 독 상태로 만들고 스피드를 떨어뜨린다.', 'Poisons the target and lowers its Speed by one stage.'),
    (675, 'throat-chop', '지옥찌르기', 'dark', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'silence', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '이 기술에 맞은 상대는 지옥의 고통 때문에 2턴 동안 소리 기술을 낼 수 없다.', 'Prevents the target from using sound-based moves for two turns.'),
    (676, 'pollen-puff', '꽃가루경단', 'bug', 90, 100, 15, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '상대에게는 폭발하는 경단을 사용하여 공격한다. 같은 편에게는 회복하는 경단을 준다.', 'Damages opponents, but heals allies for 50% of their max HP.'),
    (678, 'psychic-terrain', '사이코필드', 'psychic', NULL, NULL, 10, 'status', 0, 'entire-field', 'whole-field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 땅에 있으면 선제공격을 받지 않는다. 에스퍼타입의 위력이 올라간다.', 'Protects Pokémon on the ground from priority moves and increases the power of their  Psychic moves by 50%.'),
    (679, 'lunge', '덤벼들기', 'bug', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '전력으로 상대에게 덤벼들며 공격한다. 상대의 공격을 떨어뜨린다.', 'Lowers the target’s Attack by one stage after inflicting damage.'),
    (680, 'fire-lash', '불꽃채찍', 'fire', 80, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '불타는 채찍으로 상대를 친다. 공격을 받은 상대는 방어가 떨어진다.', 'Lowers the target’s Defense by one stage after inflicting damage.'),
    (681, 'power-trip', '기어오르기', 'dark', 20, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '자신의 강함을 뻐기고 공격한다. 자신의 능력이 올라가 있는 만큼 위력이 오른다.', 'Power is higher the more the user’s stats have been raised, to a maximum of 31×.'),
    (682, 'burn-up', '불사르기', 'fire', 130, 100, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '전신의 불꽃을 모두 태워서 큰 데미지를 준다. 자신의 불꽃타입이 없어진다.', 'Removes the user’s Fire type after inflicting damage.'),
    (683, 'speed-swap', '스피드스왑', 'psychic', NULL, NULL, 10, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 스피드와 자신의 스피드를 교체한다.', 'Exchanges the user’s Speed with the target’s.'),
    (684, 'smart-strike', '스마트혼', 'steel', 70, NULL, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '뾰족한 뿔로 상대를 꿰찔러서 공격한다. 공격은 반드시 명중한다.', 'Never misses.'),
    (688, 'trop-kick', '트로피컬킥', 'grass', 70, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '남쪽 나라에서 유래된 뜨거운 킥을 상대에게 날린다. 상대의 공격을 떨어뜨린다.', 'Lowers the target’s Attack by one stage after inflicting damage.'),
    (689, 'instruct', '지휘', 'psychic', NULL, NULL, 15, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대에게 지시하여 상대가 쓴 기술을 다시 한번 쓰게 할 수 있다.', 'Forces the target to repeat its last used move.'),
    (690, 'beak-blast', '부리캐논', 'flying', 100, 100, 15, 'physical',  -3, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '먼저 부리를 가열시킨 다음 공격을 날린다. 가열 중에 만지면 화상을 입는다.', 'Inflicts a burn on any Pokémon that makes contact before the attack.'),
    (691, 'clanging-scales', '스케일노이즈', 'dragon', 110, 100, 5, 'special', 0, 'all-opponents', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '전신의 비늘을 비벼서 큰 소리를 내 공격한다. 공격 후 자신의 방어가 떨어진다.', 'Lowers the user’s Defense by one stage after inflicting damage.'),
    (693, 'brutal-swing', '세차게휘두르기', 'dark', 60, 100, 20, 'physical', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '자신의 몸을 세차게 휘둘러서 상대에게 데미지를 준다.', 'Inflicts regular damage with no additional effect.'),
    (694, 'aurora-veil', '오로라베일', 'ice', NULL, NULL, 20, 'status', 0, 'users-field', 'field-effect', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 물리와 특수 기술의 데미지를 약하게 한다. 싸라기눈일 때만 쓸 수 있다.', 'Reduces damage five turns, but must be used during hail.'),
    (706, 'psychic-fangs', '사이코팽', 'psychic', 85, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, true, false, false, false, false, false, false, false, false, false, '사이코 파워로 물어서 상대를 공격한다. 빛의장막이나 리플렉터도 파괴할 수 있다.', 'Destroys Reflect and Light Screen.'),
    (707, 'stomping-tantrum', '분함의발구르기', 'ground', 75, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '분함을 발판 삼아 공격한다. 앞 턴에서 기술이 빗나갔다면 위력이 배가 된다.', 'Has double power if the user’s last move failed.'),
    (709, 'accelerock', '액셀록', 'rock', 40, 100, 20, 'physical', 1, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '재빠른 스피드로 상대에게 부딪쳐서 공격한다. 반드시 선제공격할 수 있다.', 'Inflicts regular damage with no additional effect.'),
    (710, 'liquidation', '아쿠아브레이크', 'water', 85, 100, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 20, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '물의 힘으로 상대에게 부딪쳐서 공격한다. 상대의 방어를 떨어뜨릴 때가 있다.', 'Has a chance to lower the target’s Defense by one stage.'),
    (715, 'tearful-look', '눈물그렁그렁', 'normal', NULL, NULL, 20, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '눈물을 그렁그렁거려 상대의 전의를 상실하게 한다. 상대의 공격과 특수공격이 떨어진다.', 'Lowers the target’s Attack and Special Attack by one stage.'),
    (747, 'stuff-cheeks', '볼가득넣기', 'normal', NULL, NULL, 10, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '지니고 있는 나무열매를 먹고 방어를 크게 올린다.', 'Cures the entire party of major status effects after inflicting damage.'),
    (748, 'no-retreat', '배수의진', 'fighting', NULL, NULL, 5, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 모든 능력이 올라가지만 교체하거나 도망칠 수 없게 된다.', 'Hits twice in one turn, with a chance to make the target flinch.'),
    (750, 'magic-powder', '마법가루', 'psychic', NULL, 100, 20, 'status', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, true, false, false, false, false, false, false, false, '마법가루를 날려서 상대를 에스퍼타입으로 바꾼다.', NULL),
    (751, 'dragon-darts', '드래곤애로', 'dragon', 50, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 2, false, false, false, false, false, false, false, false, false, false, false, false, '드라꼰으로 2번 공격한다. 상대가 2마리일 때는 각각 1번씩 공격한다.', NULL),
    (752, 'teatime', '다과회', 'normal', NULL, NULL, 10, 'status', 0, 'all-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '다과회를 열어서 배틀에 나와 있는 포켓몬이 각각 지니고 있는 나무열매를 먹는다.', NULL),
    (775, 'clangorous-soul', '소울비트', 'dragon', NULL, 100, 5, 'status', 0, 'user', 'net-good-stats', NULL, 0, 0, 0,  -33, 0, 100, NULL, NULL, false, false, false, true, false, false, false, false, true, false, false, false, '자신의 HP를 조금 깎아서 모든 능력을 올린다.', NULL),
    (776, 'body-press', '바디프레스', 'fighting', 80, 100, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '몸을 부딪쳐서 공격한다. 방어가 높을수록 주는 데미지가 올라간다.', NULL),
    (777, 'decorate', '데코레이션', 'fairy', NULL, NULL, 15, 'status', 0, 'selected-pokemon', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '데코레이션을 해서 상대의 공격과 특수공격을 크게 올린다.', NULL),
    (779, 'snap-trap', '집게덫', 'grass', 35, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-ailment', 'trap', 100, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '집게덫으로 붙잡은 뒤 4-5턴 동안 상대를 끼워서 공격한다.', 'Prevents the target from fleeing and inflicts damage for 2-5 turns.'),
    (783, 'aura-wheel', '오라휠', 'electric', 110, 100, 10, 'physical', 0, 'selected-pokemon', 'damage-raise', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '볼주머니에 저장해둔 에너지로 공격하고 자신의 스피드를 올린다. 모르페코의 모습에 따라 타입이 바뀐다.', NULL),
    (784, 'breaking-swipe', '와이드브레이커', 'dragon', 60, 100, 15, 'physical', 0, 'all-opponents', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '강인한 꼬리를 세차게 휘둘러서 상대를 공격한다. 상대의 공격을 떨어뜨린다.', 'Lowers the target’s Attack by one stage after inflicting damage.'),
    (787, 'apple-acid', '사과산', 'grass', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '새콤한 사과에서 만들어 낸 산성 액체로 공격한다. 상대의 특수방어를 떨어뜨린다.', NULL),
    (788, 'grav-apple', 'G의힘', 'grass', 80, 100, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '높은 곳에서 사과를 떨어뜨려서 데미지를 준다. 상대의 방어를 떨어뜨린다.', 'Lowers the target’s Defense by one stage after inflicting damage.'),
    (789, 'spirit-break', '소울크래시', 'fairy', 75, 100, 15, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '맞으면 기가 꺾여버릴 것 같은 기세로 공격한다. 상대의 특수공격을 떨어뜨린다.', 'Has a chance to lower the target’s Special Attack by one stage.'),
    (791, 'life-dew', '생명의물방울', 'water', NULL, NULL, 10, 'status', 0, 'user-and-allies', 'heal', NULL, 0, 0, 0, 25, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '신비한 물을 흩뿌려서 자신과 배틀에 나와 있는 같은 편의 HP를 회복한다.', NULL),
    (796, 'steel-beam', '철제광선', 'steel', 140, 95, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '전신에서 끌어모은 강철을 빔으로 바꿔 세차게 발사한다. 자신도 데미지를 받는다.', 'Inflicts damage, and the user takes damage equal to half of its max HP, rounded up.'),
    (797, 'expanding-force', '와이드포스', 'psychic', 80, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '사이코 파워로 상대를 공격한다. 사이코필드일 때는 위력이 오르며 모든 상대에게 데미지를 준다.', 'Inflicts regular damage with no additional effect.'),
    (798, 'steel-roller', '아이언롤러', 'steel', 130, 100, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '필드를 파괴하면서 공격한다. 필드가 어떤 상태로든 변해 있지 않은 경우 기술은 실패한다.', 'Inflicts regular damage with no additional effect.'),
    (799, 'scale-shot', '스케일샷', 'dragon', 25, 90, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 5, false, false, false, false, false, false, false, false, false, false, false, false, '비늘을 쏘아서 공격한다. 2-5회 동안 연속으로 쓴다. 스피드가 올라가지만 방어가 떨어진다.', 'Boosts the user’s Speed and lowers their Defense by one stage after inflicting damage two to five times in a row.'),
    (800, 'meteor-beam', '메테오빔', 'rock', 120, 90, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '1턴째에 우주의 힘을 모아서 특수공격을 올리고 2턴째에 상대를 공격한다.', 'Inflicts regular damage with no additional effect.'),
    (801, 'shell-side-arm', '셸암즈', 'poison', 90, 100, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'poison', 20, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '물리와 특수 중 더 많은 데미지를 줄 수 있는 능력으로 공격한다. 독 상태로 만들 때가 있다.', 'Inflicts regular damage with no additional effect.'),
    (802, 'misty-explosion', '미스트버스트', 'fairy', 100, 100, 5, 'special', 0, 'all-other-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 주위에 있는 모두를 공격하지만 사용하면 기절한다. 미스트필드일 때 위력이 올라간다.', 'Inflicts regular damage with no additional effect.'),
    (803, 'grassy-glide', '그래스슬라이더', 'grass', 55, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '지면에 미끄러지듯 상대를 공격한다. 그래스필드일 때 반드시 선제공격할 수 있다.', 'Inflicts regular damage with no additional effect.'),
    (804, 'rising-voltage', '라이징볼트', 'electric', 70, 100, 20, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '지면에서 올라오는 전격으로 공격한다. 상대가 일렉트릭필드 위에 있을 때 기술의 위력이 2배가 된다.', 'Inflicts regular damage with no additional effect.'),
    (805, 'terrain-pulse', '대지의파동', 'normal', 50, 100, 10, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, true, false, false, '필드의 힘을 빌려서 공격한다. 사용했을 때의 필드 상태에 따라서 기술 타입과 위력이 바뀐다.', 'Inflicts regular damage with no additional effect.'),
    (806, 'skitter-smack', '엄습하는일격', 'bug', 70, 90, 10, 'physical', 0, 'selected-pokemon', 'damage-lower', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '배후에서 엄습해서 공격한다. 상대의 특수공격을 떨어뜨린다.', 'Inflicts regular damage with no additional effect.'),
    (807, 'burning-jealousy', '질투의불꽃', 'fire', 70, 100, 5, 'special', 0, 'all-opponents', 'damage-ailment', 'burn', 100, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '질투의 에너지로 상대를 공격한다. 그 턴에 능력이 올라간 포켓몬을 화상 상태로 만든다.', 'Inflicts regular damage with no additional effect.'),
    (808, 'lash-out', '분풀이', 'dark', 75, 100, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '상대에 대한 울분이 담긴 공격을 한다. 그 턴에 능력이 떨어져 있으면 기술의 위력이 2배가 된다.', 'Inflicts regular damage with no additional effect.'),
    (809, 'poltergeist', '폴터가이스트', 'ghost', 110, 90, 5, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 지닌 물건을 조종해서 공격한다. 상대가 도구를 지니고 있지 않으면 실패한다.', 'Inflicts regular damage with no additional effect.'),
    (810, 'corrosive-gas', '부식가스', 'poison', NULL, 100, 40, 'status', 0, 'all-other-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '주위에 있는 모든 것을 강력한 산성 가스로 뒤덮어서 지니고 있는 도구를 녹여버린다.', 'Inflicts regular damage with no additional effect.'),
    (811, 'coaching', '코칭', 'fighting', NULL, NULL, 10, 'status', 0, 'user-and-allies', 'net-good-stats', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '적절한 지도를 통해서 같은 편 전원의 공격과 방어를 올린다.', 'Inflicts regular damage with no additional effect.'),
    (812, 'flip-turn', '퀵턴', 'water', 60, 100, 20, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '공격한 뒤 굉장한 스피드로 돌아와서 교대 포켓몬과 교체한다.', 'Inflicts regular damage with no additional effect.'),
    (813, 'triple-axel', '트리플악셀', 'ice', 20, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 3, 3, true, false, false, false, false, false, false, false, false, false, false, false, '3회 연속으로 킥을 날려 공격한다. 기술이 맞을 때마다 위력이 올라간다.', 'Inflicts regular damage with no additional effect.'),
    (814, 'dual-wingbeat', '더블윙', 'flying', 40, 90, 10, 'physical', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, 2, 2, true, false, false, false, false, false, false, false, false, false, false, false, '날개를 상대에게 부딪쳐서 공격한다. 2회 연속으로 데미지를 준다.', 'Inflicts regular damage with no additional effect.'),
    (815, 'scorching-sands', '열사의대지', 'ground', 70, 100, 10, 'special', 0, 'selected-pokemon', 'damage-ailment', 'burn', 30, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '뜨겁게 달궈진 모래를 상대에게 부딪쳐서 공격한다. 화상 상태로 만들 때가 있다.', 'Has a chance to burn the target.'),
    (826, 'eerie-spell', '섬뜩한주문', 'psychic', 80, 100, 5, 'special', 0, 'selected-pokemon', 'damage', NULL, 0, 0, 0, 0, 0, 0, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '강력한 사이코 파워로 공격한다. 상대가 마지막으로 사용한 기술의 PP를 3만큼 줄인다.', 'Inflicts regular damage with no additional effect.'),
    (827, 'dire-claw', '페이탈클로', 'poison', 80, 100, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '치명적인 손톱으로 급소를 노려 공격한다. 상대를 독, 마비, 졸음 중 하나의 상태로 만들 때가 있다.', NULL),
    (828, 'psyshield-bash', '배리어러시', 'psychic', 70, 90, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '사념의 에너지를 두른 채로 상대에 부딪힌다. 자신의 방어력이 오를 때가 있다.', NULL),
    (830, 'stone-axe', '암석액스', 'rock', 65, 90, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '암석 도끼로 급소를 노려 공격한다. 흩어진 암석 파편으로 상대에게 여러 번 데미지를 준다.', NULL),
    (833, 'raging-fury', '대격분', 'fire', 120, 100, 10, 'physical', 0, 'random-opponent', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '격렬한 불꽃을 방출하면서 마구 날뛰어 공격한다. 기술을 사용한 다음 열중 상태가 된다.', NULL),
    (834, 'wave-crash', '웨이브태클', 'water', 120, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '물을 두르고 온몸으로 상대에게 부딪친다. 자신도 상당한 데미지를 입는다.', NULL),
    (836, 'mountain-gale', '빙산바람', 'ice', 100, 85, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '빙산처럼 커다란 얼음덩어리를 부딪쳐서 공격한다.', NULL),
    (838, 'headlong-rush', '들이받기', 'ground', 120, 100, 5, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '온 힘을 다한 몸통박치기를 날린다. 자신의 방어력이 떨어진다.', NULL),
    (839, 'barb-barrage', '독침천발', 'poison', 60, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '무수히 많은 독침으로 공격한다. 상대를 독 상태로 만들 때가 있다. 상대가 상태 이상인 경우 위력이 2배가 된다.', NULL),
    (841, 'bitter-malice', '천추지한', 'ghost', 75, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '동굴이 서늘해지는 원념으로 공격해서 상대를 동상 상태로 만들 때가 있다. 상대가 상태 이상인 경우 위력이 2배가 된다.', NULL),
    (842, 'shelter', '농성', 'steel', 0, NULL, 10, 'status', 0, 'user', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '피부를 강철 방패처럼 단단하게 만들어서 자신의 방어력을 올린다. 상대의 기술을 회피하기 쉬워진다.', NULL),
    (843, 'triple-arrows', '3연화살', 'fighting', 90, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '발뒤꿈치로 찍은 뒤 3개의 화살을 동시에 발사한다. 자신의 공격이 급소에 맞기 쉬워진다. 상대의 방어력을 떨어뜨린다.', NULL),
    (844, 'infernal-parade', '백귀야행', 'ghost', 60, 100, 15, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '무수히 많은 불덩이로 공격해서 상대를 화상 상태로 만들 때가 있다. 상대가 상태 이상인 경우 위력이 2배가 된다.', NULL),
    (845, 'ceaseless-edge', '비검천중파', 'dark', 65, 90, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '조개껍질 검으로 급소를 노려 공격한다. 흩어진 조개껍질 파편으로 상대에게 여러 번 데미지를 준다.', NULL),
    (853, 'axe-kick', '발꿈치찍기', 'fighting', 120, 90, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '발꿈치를 들어 올린 뒤 내리찍어 공격한다. 상대를 혼란시킬 때가 있다.빗나가면 자신이 데미지를 입는다.', NULL),
    (854, 'last-respects', '성묘', 'ghost', 50, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '동료의 한을 풀어 주기 위해 공격한다. 쓰러진 같은 편 포켓몬이 많을수록 기술의 위력이 올라간다.', NULL),
    (855, 'lumina-crash', '루미나콜리전', 'psychic', 80, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '정신에도 작용하는 기묘한 빛을 발산해서 공격한다. 상대의 특수방어를 크게 떨어뜨린다.', NULL),
    (857, 'jet-punch', '제트펀치', 'water', 60, 100, 15, 'physical', 1, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '거센 물살을 주먹에 둘러 눈에 보이지 않는 속도로 펀치를 날린다. 반드시 선제공격할 수 있다.', NULL),
    (858, 'spicy-extract', '하바네로엑기스', 'grass', 0, NULL, 15, 'status', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '어마어마하게 매운 엑기스를 발사한다. 상대의 공격이 크게 오르고 방어는 크게 떨어진다.', NULL),
    (860, 'population-bomb', '찍찍베기', 'normal', 20, 90, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '여기저기서 동료들을 모아서 화려한 콤비네이션으로 공격한다. 1~10회 연속으로 공격한다.', NULL),
    (861, 'ice-spinner', '아이스스피너', 'ice', 80, 100, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '발에 얇은 얼음을 두르고 빙글빙글 회전하며 부딪친다. 회전 운동에 의해 필드가 파괴된다.', NULL),
    (863, 'revival-blessing', '회생의기도', 'normal', 0, NULL, 1, 'status', 0, 'fainting-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자애로운 마음으로 기도를 하여 기절한 교대 포켓몬을 HP가 절반인 상태로 부활시킨다.', NULL),
    (864, 'salt-cure', '소금절이', 'rock', 40, 100, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대를 소금절이 상태로 만들어 매 턴 데미지를 준다. 강철타입이나 물타입에게 더 고통스럽다.', NULL),
    (866, 'mortal-spin', '킬러스핀', 'poison', 30, 100, 15, 'physical', 0, 'all-opponents', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '회전해서 상대를 공격한다. 조이기, 김밥말이, 씨뿌리기 등의 효과를 날려 버린다. 상대를 독 상태로 만든다.', NULL),
    (869, 'kowtow-cleave', '도각참', 'dark', 85, NULL, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '머리를 조아려 상대를 방심하게 만든 뒤에 베어 버린다. 공격은 반드시 명중한다.', NULL),
    (870, 'flower-trick', '트릭플라워', 'grass', 70, NULL, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '숨겨진 장치가 있는 꽃다발을 상대에게 던져서 공격한다. 반드시 명중하며 급소에 맞는다.', NULL),
    (871, 'torch-song', '플레어송', 'fire', 80, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '활활 타오르는 불꽃을 노래하듯 뿜어서 상대를 태워 버린다. 자신의 특수공격을 올린다.', NULL),
    (872, 'aqua-step', '아쿠아스텝', 'water', 80, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, true, false, false, false, '물 흐르듯 민첩하고 경쾌한 발재간으로 상대를 농락하여 데미지를 준다.자신의 스피드를 올린다.', NULL),
    (873, 'raging-bull', '레이징불', 'normal', 90, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '분노해 날뛰는 성난소의 맹렬한 태클. 폼에 따라 기술의 타입이 달라지고 빛의장막이나 리플렉터 등도 파괴할 수 있다.', NULL),
    (874, 'make-it-rain', '골드러시', 'steel', 120, 100, 5, 'special', 0, 'all-opponents', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '대량의 코인을 날려서 공격한다. 자신의 특수공격이 떨어진다. 배틀 후에 돈을 받을 수 있다.', NULL),
    (880, 'shed-tail', '꼬리자르기', 'normal', 0, NULL, 10, 'status', 0, 'user', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '사용자 HP의 1/2를 깎아서 대타가 되는 분신을 만든 다음, 교대 포켓몬과 교체한다.', NULL),
    (881, 'chilly-reception', '썰렁개그', 'ice', 0, NULL, 10, 'status', 0, 'entire-field', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자리를 얼어붙게 만드는 개그를 하고 교대 포켓몬과 교체한다. 5턴 동안 눈을 내리게 한다.', NULL),
    (882, 'tidy-up', '정리정돈', 'normal', 0, NULL, 10, 'status', 0, 'user', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '압정뿌리기, 스텔스록, 끈적끈적네트, 독압정, 대타출동을 모두 정리한다. 자신의 공격과 스피드가 올라간다.', NULL),
    (883, 'snowscape', '설경', 'ice', 0, NULL, 10, 'status', 0, 'entire-field', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '5턴 동안 눈을 내리게 한다. 얼음타입의 방어가 올라간다.', NULL),
    (884, 'pounce', '달려들기', 'bug', 50, 100, 20, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '상대에게 달려들어 공격한다. 상대의 스피드를 떨어뜨린다.', NULL),
    (885, 'trailblaze', '개척하기', 'grass', 50, 100, 20, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '풀숲에서 튀어나오듯이 공격한다. 경쾌한 발재간으로 자신의 스피드를 올린다.', NULL),
    (886, 'chilling-water', '찬물끼얹기', 'water', 50, 100, 20, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '상대의 기운이 빠질 정도로 차가운 물을 끼얹어서 공격한다. 상대의 공격을 떨어뜨린다.', NULL),
    (888, 'twin-beam', '트윈빔', 'psychic', 40, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '두 눈에서 불가사의한 광선을 발사해서 공격한다. 2회 연속으로 데미지를 준다.', NULL),
    (889, 'rage-fist', '분노의주먹', 'ghost', 50, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, true, false, false, false, false, false, false, false, false, false, false, '분노를 에너지로 바꿔서 공격한다. 받은 공격의 횟수가 많을수록 기술의 위력이 올라간다.', NULL),
    (890, 'armor-cannon', '아머캐논', 'fire', 120, 100, 5, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '자신의 갑옷을 활활 타오르는 탄환으로 발사해서 공격한다. 자신의 방어와 특수방어가 떨어진다.', NULL),
    (891, 'bitter-blade', '원념의칼', 'fire', 90, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, true, false, false, false, false, '현세의 미련을 칼끝에 담아 베어 버린다. 입힌 데미지의 절반에 해당하는 HP를 회복할 수 있다.', NULL),
    (892, 'double-shock', '전광쌍격', 'electric', 120, 100, 5, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '전신의 전기를 모두 방출해서 큰 데미지를 준다. 자신의 전기타입이 없어진다.', NULL),
    (893, 'gigaton-hammer', '거대해머', 'steel', 160, 100, 5, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '거대한 해머를 온몸으로 휘둘러서 공격한다. 이 기술은 2회 연속으로 쓸 수 없다.', NULL),
    (894, 'comeuppance', '앙갚음', 'dark', 1, 100, 10, 'physical', 0, 'specific-move', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '기술을 쓰기 전에 마지막으로 받은 기술의 데미지를 늘려서 기술을 쓴 상대에게 돌려준다.', NULL),
    (895, 'aqua-cutter', '아쿠아커터', 'water', 70, 100, 20, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, true, false, false, false, false, '압력을 가한 물을 칼날처럼 분사해서 상대를 베어 가른다. 급소에 맞기 쉽다.', NULL),
    (902, 'matcha-gotcha', '휘적휘적포', 'grass', 80, 90, 15, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '휘저은 차를 대포처럼 발사해 준 데미지의 절반을 HP로 회복한다. 화상 상태로 만들 때도 있다.', NULL),
    (903, 'syrup-bomb', '시럽봄', 'grass', 60, 85, 10, 'special', 0, 'selected-pokemon', 'unique', NULL, 0, 0, 0, 0, 0, 100, NULL, NULL, false, false, false, false, false, true, false, false, false, false, false, false, '끈적끈적한 물엿을 폭발시킨다. 상대를 물엿범벅 상태로 만들어서 3턴 동안 계속 스피드를 떨어뜨린다', NULL),
    (905, 'electro-shot', '일렉트로빔', 'electric', 130, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '1턴째에 전기를 모아서 특수공격을 올리고 2턴째에 고압의 전기를 발사한다. 비가 오는 날씨일 때는 바로 발사할 수 있다.', NULL),
    (907, 'fickle-beam', '변덕레이저', 'dragon', 80, 100, 5, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, false, false, false, false, false, false, false, false, false, '광선을 발사해서 공격한다. 가끔 다른 머리도 협력해서 레이저를 발사하여 위력이 2배가 된다.', NULL),
    (912, 'hard-press', '하드프레스', 'steel', 0, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '팔이나 집게로 상대를 압박한다. 상대의 HP가 남아 있을수록 위력이 올라간다.', NULL),
    (913, 'dragon-cheer', '드래곤옐', 'dragon', 0, 0, 15, 'status', 0, 'all-allies', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '용의 북돋움으로 사기를 높여서 같은 편의 기술이 급소에 맞기 쉬워진다. 드래곤타입이면 더욱더 사기가 북돋는다.', NULL),
    (914, 'alluring-voice', '매혹의보이스', 'fairy', 80, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '천사와도 같은 노랫소리로 상대를 공격한다.그 턴에 능력이 올라간 포켓몬을 혼란 상태로 만든다.', NULL),
    (915, 'temper-flare', '열불내기', 'fire', 75, 100, 10, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '자포자기하는 자세로 공격한다. 앞 턴에서 기술이 빗나갔다면 위력이 배가 된다.', NULL),
    (916, 'supercell-slam', '썬더다이브', 'electric', 100, 95, 15, 'physical', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '몸에 전기를 두르고 상대를 덮친다. 빗나가면 자신이 데미지를 입는다.', NULL),
    (917, 'psychic-noise', '사이코노이즈', 'psychic', 75, 100, 10, 'special', 0, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, true, false, false, false, false, false, false, false, false, '불쾌한 음파를 상대에게 날려서 공격한다. 2턴 동안 상대는 기술이나 특성 또는 지니고 있는 도구로 HP를 회복할 수 없게 된다.', NULL),
    (918, 'upper-hand', '기선제압', 'fighting', 65, 100, 15, 'physical', 3, 'selected-pokemon', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, true, false, false, false, false, false, false, false, false, false, false, false, '움직임에 반응하여 손바닥으로 밀쳐서 상대를 풀죽게 한다. 상대가 쓴 기술이 선제공격 기술이 아니면 실패한다.', NULL);
INSERT INTO abilities
    (id, name, ko_name, description, effect)
VALUES
    (1, 'stench', '악취', '악취를 풍겨서 공격했을 때 상대가 풀죽을 때가 있다.', 'Has a 10% chance of making target Pokémon flinch with each hit.'),
    (2, 'drizzle', '잔비', '등장했을 때 날씨를 비로 만든다.', 'Summons rain that lasts indefinitely upon entering battle.'),
    (3, 'speed-boost', '가속', '매 턴 스피드가 올라간다.', 'Raises Speed one stage after each turn.'),
    (4, 'battle-armor', '전투무장', '단단한 껍질에 보호받아 상대의 공격이 급소에 맞지 않는다.', 'Protects against critical hits.'),
    (5, 'sturdy', '옹골참', '상대 기술을 받아도 일격으로 쓰러지지 않는다. 일격필살 기술도 효과 없다.', 'Prevents being KOed from full HP, leaving 1 HP instead.  Protects against the one-hit KO moves regardless of HP.'),
    (6, 'damp', '습기', '주변을 습하게 함으로써 자폭 등 폭발하는 기술을 아무도 못 쓰게 한다.', 'Prevents Self-Destruct, Explosion, and Aftermath from working while the Pokémon is in battle.'),
    (7, 'limber', '유연', '유연한 몸으로 인해 마비 상태가 되지 않는다.', 'Prevents paralysis.'),
    (8, 'sand-veil', '모래숨기', '모래바람일 때 회피율이 올라간다.', 'Increases evasion to 1.25× during a sandstorm.  Protects against sandstorm damage.'),
    (9, 'static', '정전기', '정전기를 몸에 둘러 접촉한 상대를 마비시킬 때가 있다.', 'Has a 30% chance of paralyzing attacking Pokémon on contact.'),
    (10, 'volt-absorb', '축전', '전기타입의 기술을 받으면 데미지를 받지 않고 회복한다.', 'Absorbs Electric moves, healing for 1/4 max HP.'),
    (11, 'water-absorb', '저수', '물타입의 기술을 받으면 데미지를 받지 않고 회복한다.', 'Absorbs Water moves, healing for 1/4 max HP.'),
    (12, 'oblivious', '둔감', '둔감해서 헤롱헤롱이나 도발 상태가 되지 않는다.', 'Prevents infatuation and protects against Captivate.'),
    (13, 'cloud-nine', '날씨부정', '모든 날씨의 영향이 없어진다.', 'Negates all effects of weather, but does not prevent the weather itself.'),
    (14, 'compound-eyes', '복안', '복안을 가지고 있어 기술의 명중률이 올라간다.', 'Increases moves'' accuracy to 1.3×.'),
    (15, 'insomnia', '불면', '잠들지 못하는 체질이라 잠듦 상태가 되지 않는다.', 'Prevents sleep.'),
    (17, 'immunity', '면역', '체내에 면역을 가지고 있어 독 상태가 되지 않는다.', 'Prevents poison.'),
    (18, 'flash-fire', '타오르는불꽃', '불꽃타입의 기술을 받으면 불꽃을 받아서 자신이 사용하는 불꽃타입의 기술이 강해진다.', 'Protects against Fire moves.  Once one has been blocked, the Pokémon''s own Fire moves inflict 1.5× damage until it leaves battle.'),
    (19, 'shield-dust', '인분', '인분에 보호받아 기술의 추가 효과를 받지 않게 된다.', 'Protects against incoming moves'' extra effects.'),
    (20, 'own-tempo', '마이페이스', '마이페이스라서 혼란 상태가 되지 않는다.', 'Prevents confusion.'),
    (21, 'suction-cups', '흡반', '흡반으로 지면에 달라붙어 포켓몬을 교체시키는 기술이나 도구의 효과를 발휘하지 못하게 한다.', 'Prevents being forced out of battle by other Pokémon''s moves.'),
    (22, 'intimidate', '위협', '등장했을 때 위협해서 상대를 위축시켜 상대의 공격을 떨어뜨린다.', 'Lowers opponents'' Attack one stage upon entering battle.'),
    (23, 'shadow-tag', '그림자밟기', '상대의 그림자를 밟아 도망치거나 교체할 수 없게 한다.', 'Prevents opponents from fleeing or switching out.'),
    (24, 'rough-skin', '까칠한피부', '공격을 받았을 때 자신에게 접촉한 상대를 까칠까칠한 피부로 상처를 입힌다.', 'Damages attacking Pokémon for 1/8 their max HP on contact.'),
    (26, 'levitate', '부유', '땅에서 뜨는 것으로 땅타입의 기술을 받지 않는다.', 'Evades Ground moves.'),
    (27, 'effect-spore', '포자', '공격으로 자신에게 접촉한 상대를 독이나 마비, 잠듦 상태로 만들 때가 있다.', 'Has a 30% chance of inflcting either paralysis, poison, or sleep on attacking Pokémon on contact.'),
    (28, 'synchronize', '싱크로', '자신이 걸린 독이나 마비, 화상을 상대에게 옮긴다.', 'Copies burns, paralysis, and poison received onto the Pokémon that inflicted them.'),
    (29, 'clear-body', '클리어바디', '상대 기술이나 특성으로 능력을 떨어뜨릴 수 없다.', 'Prevents stats from being lowered by other Pokémon.'),
    (30, 'natural-cure', '자연회복', '지닌 포켓몬으로 돌아오면 상태 이상이 회복된다.', 'Cures any major status ailment upon switching out.'),
    (31, 'lightning-rod', '피뢰침', '전기타입의 기술을 자신에게 끌어모아 데미지를 받지 않고 특수공격을 올린다.', 'Redirects single-target Electric moves to this Pokémon where possible.  Absorbs Electric moves, raising Special Attack one stage.'),
    (33, 'swift-swim', '쓱쓱', '비가 오는 날씨일 때 스피드가 올라간다.', 'Doubles Speed during rain.'),
    (34, 'chlorophyll', '엽록소', '날씨가 맑을 때 스피드가 올라간다.', 'Doubles Speed during strong sunlight.'),
    (35, 'illuminate', '발광', '주변을 밝게 하는 것으로 야생 포켓몬과 만나기 쉬워진다.', 'Doubles the wild encounter rate.'),
    (36, 'trace', '트레이스', '등장했을 때 상대의 특성을 트레이스해서 같은 특성이 된다.', 'Copies an opponent''s ability upon entering battle.'),
    (37, 'huge-power', '천하장사', '물리공격의 위력이 2배가 된다.', 'Doubles Attack in battle.'),
    (38, 'poison-point', '독가시', '자신과 접촉한 상대를 독 상태로 만들 때가 있다.', 'Has a 30% chance of poisoning attacking Pokémon on contact.'),
    (39, 'inner-focus', '정신력', '단련한 정신으로 인하여 상대의 공격에 풀죽지 않는다.', 'Prevents flinching.'),
    (40, 'magma-armor', '마그마의무장', '뜨거운 마그마를 몸에 둘러서 얼음 상태가 되지 않는다.', 'Prevents freezing.'),
    (43, 'soundproof', '방음', '소리를 차단하는 것으로 소리 공격을 받지 않는다.', 'Protects against sound-based moves.'),
    (44, 'rain-dish', '젖은접시', '비가 오는 날씨일 때 조금씩 HP를 회복한다.', 'Heals for 1/16 max HP after each turn during rain.'),
    (45, 'sand-stream', '모래날림', '등장했을 때 날씨를 모래바람으로 만든다.', 'Summons a sandstorm that lasts indefinitely upon entering battle.'),
