    (166, 'flower-veil', '플라워베일', '같은 편의 풀타입 포켓몬은 능력이 떨어지지 않고 상태 이상도 되지 않는다.', 'Protects friendly Grass Pokémon from having their stats lowered by other Pokémon.'),
    (167, 'cheek-pouch', '볼주머니', '어떤 나무열매라도 먹으면 HP도 회복한다.', 'Restores HP upon eating a Berry, in addition to the Berry''s effect.'),
    (168, 'protean', '변환자재', '자신이 사용한 기술과 같은 타입으로 변화한다.', 'Changes the bearer''s type to match each move it uses.'),
    (169, 'fur-coat', '퍼코트', '상대로부터 받는 물리 기술의 데미지가 절반이 된다.', 'Halves damage from physical attacks.'),
    (170, 'magician', '매지션', '기술을 맞은 상대의 도구를 빼앗아 버린다.', 'Steals the target''s held item when the bearer uses a damaging move.'),
    (171, 'bulletproof', '방탄', '상대 구슬이나 폭탄 등 기술을 막을 수 있다.', 'Protects against bullet, ball, and bomb-based moves.'),
    (172, 'competitive', '승기', '능력이 떨어지면 특수공격이 크게 올라간다.', 'Raises Special Attack by two stages upon having any stat lowered.'),
    (173, 'strong-jaw', '옹골찬턱', '턱이 튼튼하여 무는 기술의 위력이 올라간다.', 'Strengthens biting moves to 1.5× their power.'),
    (174, 'refrigerate', '프리즈스킨', '노말타입의 기술이 얼음타입이 된다. 위력이 조금 올라간다.', 'Turns the bearer''s Normal moves into Ice moves and strengthens them to 1.3× their power.'),
    (175, 'sweet-veil', '스위트베일', '같은 편의 포켓몬이 잠들지 않게 된다.', 'Prevents friendly Pokémon from sleeping.'),
    (176, 'stance-change', '배틀스위치', '공격 기술을 쓰면 블레이드폼으로 기술 킹실드를 쓰면 실드폼으로 변한다.', 'Changes Aegislash to Blade Forme before using a damaging move, or Shield Forme before using King’s Shield.'),
    (177, 'gale-wings', '질풍날개', 'HP가 꽉 찼을 때 비행타입의 기술을 먼저 쓸 수 있다.', 'Raises Flying moves'' priority by one stage.'),
    (178, 'mega-launcher', '메가런처', '파동 기술의 위력이 올라간다.', 'Strengthens aura and pulse moves to 1.5× their power.'),
    (180, 'symbiosis', '공생', '같은 편이 도구를 쓰면 자신이 지니고 있는 도구를 같은 편에게 건넨다.', 'Passes the bearer''s held item to an ally when the ally uses up its item.'),
    (181, 'tough-claws', '단단한발톱', '상대에게 접촉하는 기술의 위력이 올라간다.', 'Strengthens moves that make contact to 1.33× their power.'),
    (182, 'pixilate', '페어리스킨', '노말타입의 기술이 페어리타입이 된다. 위력이 조금 올라간다.', 'Turns the bearer''s Normal moves into Fairy moves and strengthens them to 1.3× their power.'),
    (183, 'gooey', '미끈미끈', '공격으로 자신과 접촉한 상대의 스피드를 떨어뜨린다.', 'Lowers attacking Pokémon''s Speed by one stage on contact.'),
    (184, 'aerilate', '스카이스킨', '노말타입의 기술이 비행타입이 된다. 위력이 조금 올라간다.', 'Turns the bearer''s Normal moves into Flying moves and strengthens them to 1.3× their power.'),
    (185, 'parental-bond', '부자유친', '부모와 자식 2마리로 2번 공격할 수 있다.', 'Lets the bearer hit twice with damaging moves.  The second hit has half power.'),
    (187, 'fairy-aura', '페어리오라', '전원의 페어리타입 기술이 강해진다.', 'Strengthens Fairy moves to 1.33× their power for all friendly and opposing Pokémon.'),
    (192, 'stamina', '지구력', '공격을 받으면 방어가 올라간다.', 'Raises this Pokémon''s Defense by one stage when it takes damage from a move.'),
    (196, 'merciless', '무도한행동', '독 상태의 상대를 공격하면 반드시 급소에 맞는다.', 'This Pokémon''s moves critical hit against poisoned targets.'),
    (199, 'water-bubble', '수포', '자신을 향하는 불꽃타입 기술의 위력을 떨어뜨린다. 화상을 입지 않는다.', 'Halves damage from Fire moves, doubles damage of Water moves, and prevents burns.'),
    (201, 'berserk', '발끈', '상대의 공격으로 HP가 절반이 되면 특수공격이 올라간다.', 'Raises this Pokémon''s Special Attack by one stage every time its HP drops below half.'),
    (202, 'slush-rush', '눈치우기', '날씨가 싸라기눈일 때 스피드가 올라간다.', 'During Hail, this Pokémon has double Speed.'),
    (203, 'long-reach', '원격', '모든 기술을 상대에게 접촉하지 않고 사용할 수 있다.', 'This Pokémon''s moves do not make contact.'),
    (204, 'liquid-voice', '촉촉보이스', '모든 소리 기술이 물타입이 된다.', 'Sound-based moves become Water-type.'),
    (207, 'surge-surfer', '서핑테일', '일렉트릭필드일 때 스피드가 2배가 된다.', 'Doubles this Pokémon''s Speed on Electric Terrain.'),
    (209, 'disguise', '탈', '몸을 덮는 탈로 1번 공격을 막을 수 있다.', 'Prevents the first instance of battle damage.'),
    (212, 'corrosion', '부식', '강철타입이나 독타입도 독 상태로 만들 수 있다.', 'This Pokémon can inflict poison on Poison and Steel Pokémon.'),
    (214, 'queenly-majesty', '여왕의위엄', '상대에게 위압감을 줘서 이쪽을 향한 선제 기술을 사용할 수 없게 한다.', 'Opposing Pokémon cannot use priority attacks.'),
    (215, 'innards-out', '내용물분출', '상대가 쓰러뜨렸을 때 HP의 남은 양만큼 상대에게 데미지를 준다.', 'When this Pokémon faints from an opponent''s move, that opponent takes damage equal to the HP this Pokémon had remaining.'),
    (218, 'fluffy', '복슬복슬', '상대로부터 받은 접촉하는 기술의 데미지를 반감시키지만 불꽃타입 기술의 데미지는 2배가 된다.', 'Damage from contact moves is halved.  Damage from Fire moves is doubled.'),
    (222, 'receiver', '리시버', '쓰러진 같은 편의 특성을 이어받아 같은 특성이 된다.', 'When an ally faints, this Pokémon gains its Ability.'),
    (226, 'electric-surge', '일렉트릭메이커', '등장했을 때 일렉트릭필드를 사용한다.', 'When this Pokémon enters battle, it changes the terrain to Electric Terrain.'),
    (227, 'psychic-surge', '사이코메이커', '등장했을 때 사이코필드를 사용한다.', 'When this Pokémon enters battle, it changes the terrain to Psychic Terrain.'),
    (240, 'mirror-armor', '미러아머', '자신이 받는 능력 다운 효과에 한해 되받아친다.', 'Reflects any stat-lowering effects.'),
    (242, 'stalwart', '굳건한신념', '상대의 기술을 끌어모으는 특성이나 기술의 영향을 받지 않는다.', 'Ignores moves and abilities that draw in moves.'),
    (245, 'sand-spit', '모래뿜기', '공격을 받으면 모래바람을 일으킨다.', 'Creates a sandstorm when hit by an attack.'),
    (247, 'ripen', '숙성', '나무열매를 숙성시켜서 효과가 2배가 된다.', 'Doubles the effect of berries.'),
    (250, 'mimicry', '의태', '필드의 상태에 따라 포켓몬의 타입이 바뀐다.', 'Changes type depending on the terrain.'),
    (251, 'screen-cleaner', '배리어프리', '등장했을 때 상대와 같은 편의 빛의장막, 리플렉터, 오로라베일의 효과가 사라진다.', 'Nullifies effects of Light Screen, Reflect, and Aurora Veil.'),
    (254, 'wandering-spirit', '떠도는영혼', '접촉하는 기술로 공격해온 포켓몬과 특성을 바꾼다.', 'Swaps abilities with opponents on contact.'),
    (258, 'hunger-switch', '꼬르륵스위치', '턴이 끝날 때마다 배부른 모양, 배고픈 모양, 배부른 모양...으로 번갈아서 모습을 바꾼다.', 'Causes Morpeko to change its form each turn, alternating between Full Belly Mode and Hangry Mode'),
    (259, 'quick-draw', '퀵드로', '상대보다 먼저 행동할 수도 있다.', 'Enables the Pokémon to move first occasionally.'),
    (260, 'unseen-fist', '보이지않는주먹', '상대에게 접촉하는 기술을 사용하면 방어의 효과를 무시하고 공격할 수 있다.', 'Contact moves can strike through Protect/Detect.'),
    (261, 'curious-medicine', '기묘한약', '등장했을 때 조개껍질에서 약을 흩뿌려서 능력 변화를 원래대로 되돌린다.', 'Resets all stat changes upon entering battlefield.'),
    (272, 'purifying-salt', '정화의소금', '깨끗한 소금에 의해 상태 이상이 되지 않는다. 고스트타입 기술의 데미지를 반감시킨다.', 'Protects from status conditions and halves damage from Ghost-type moves.'),
    (278, 'zero-to-hero', '마이티체인지', '지닌 포켓몬으로 돌아오면 마이티폼으로 변한다.', 'Transforms into its Hero Form when switching out.'),
    (280, 'electromorphosis', '전기로바꾸기', '공격을 받으면 딱 한 번 전기 타입 기술의 위력을 올린다.', 'When hit by an attack, the power of the next Electric-type move it uses is doubled.'),
    (283, 'good-as-gold', '황금몸', '산화하지 않는 튼튼한 황금몸 덕분에 상대의 변화 기술의 영향을 받지 않는다.', 'Gives immunity to status moves.'),
    (290, 'opportunist', '편승', '상대의 능력이 올라가면 자신도 편승해서 똑같이 자신도 올린다.', 'Copies stat boosts by the opponent.'),
    (291, 'cud-chew', '되새김질', '한 번에 한하여 나무열매를 먹으면 다음 턴이 끝날 때 위에서 꺼내서 또 먹는다.', 'Causes the Pokémon to reuse an already consumed Berry at the end of the next turn.'),
    (292, 'sharpness', '예리함', '상대를 베는 기술의 위력이 올라간다.', 'Powers up slicing moves.'),
    (293, 'supreme-overlord', '총대장', '등장했을 때 지금까지 쓰러진 같은 편의 수가 많을수록 조금씩 공격과 특수공격이 올라간다.', 'Attack and Special Attack are boosted for each party Pokémon that has been defeated.'),
    (295, 'toxic-debris', '독치장', '물리 기술로 데미지를 받으면 상대의 발밑에 독압정을 뿌린다.', 'Scatters poison spikes at the feet of the opposing team when the Pokémon takes damage from physical moves.'),
    (296, 'armor-tail', '테일아머', '머리를 감싸고 있는 수수께끼의 꼬리가 이쪽을 향한 선제 기술을 사용할 수 없게 한다.', 'Prevents the opponent from using any moves that have priority, such as Quick Attack.'),
    (297, 'earth-eater', '흙먹기', '땅타입의 기술로 공격받으면 데미지를 받지 않고 회복한다.', 'Restores HP when hit by a Ground-type move.'),
    (298, 'mycelium-might', '균사의힘', '변화 기술을 사용할 때 반드시 행동이 느려지지만 상대 특성에 방해받지 않는다.', 'Status moves go last, but are not affected by the opponent''s ability.'),
    (300, 'supersweet-syrup', '감미로운꿀', '처음 등장했을 때 감미로운 꿀의 향기를 흩뿌려서 상대의 회피율을 떨어뜨린다.', 'Once per battle, when a Pokémon with Supersweet Syrup enters the battle, it lowers the evasion stat of all adjacent opponents by one stage.'),
    (301, 'hospitality', '대접', '등장했을 때 같은 편을 대접해서 HP를 조금 회복시킨다.', 'When a Pokémon with Hospitality enters a battle, it restores HP for an ally by 25%.'),
    (308, 'piercing-drill', '관통드릴', '접촉 기술을 사용할 때 상대의 방어 효과를 무시하고 본래 데미지의 1/4만큼 데미지를 준다. 상대의 방어 효과 이외에는 발동된다.', 'When the Pokémon uses contact moves, it can hit even targets that are protecting themselves.'),
    (309, 'dragonize', '드래곤스킨', '사용하는 노말 타입 기술이 위력이 1.2배가 되며 모두 드래곤 타입이 된다.', 'The Pokémon''s Normal-type moves become Dragon-type moves and their power is boosted by 20%.'),
    (310, 'mega-sol', '메가솔라', '이 특성을 가진 포켓몬이 기술을 사용하면, 쾌청 상태일 때와 같은 효과를 받는다.', 'The Pokémon can use its moves as if the weather were harsh sunlight.'),
    (311, 'spicy-spray', '하바네로분출', '기술로 대미지를 받으면 상대를 화상 상태로 만든다.', 'When the Pokémon takes damage from a move, it burns the attacker.'),
    (312, 'eelevate', '천정부지', '땅 타입 기술을 받지 않는다. 상대 포켓몬을 쓰러뜨릴 시, 가장 높은 능력이 1랭크 상승한다.', 'The Pokémon floats off the ground, making it immune to Ground-type moves, as well as the Spikes, Toxic Spikes, and Sticky Web statuses. When the Pokémon knocks out a target with an attack, its highest stat is boosted by 1 stage.'),
    (313, 'fire-mane', '불꽃의갈기', '불꽃 타입 기술의 위력이 1.5배 상승한다.', 'Boosts the power of the Pokémon''s Fire-type moves by 50%.');
INSERT INTO items
    (id, name, ko_name, category, fling_power, description, effect)
VALUES
    (126, 'cheri-berry', '버치열매', 'medicine', 10, '포켓몬에게 지니게 하면 마비를 회복한다.', 'Held: Consumed when paralyzed to cure paralysis.'),
    (127, 'chesto-berry', '유루열매', 'medicine', 10, '포켓몬에게 지니게 하면 잠듦을 회복한다.', 'Held: Consumed when asleep to cure sleep.'),
    (128, 'pecha-berry', '복슝열매', 'medicine', 10, '포켓몬에게 지니게 하면 독을 회복한다.', 'Held: Consumed when poisoned to cure poison.'),
    (129, 'rawst-berry', '복분열매', 'medicine', 10, '포켓몬에게 지니게 하면 화상을 회복한다.', 'Held: Consumed when burned to cure a burn.'),
    (130, 'aspear-berry', '배리열매', 'medicine', 10, '포켓몬에게 지니게 하면 얼음을 회복한다.', 'Held: Consumed when frozen to cure frozen.'),
    (132, 'oran-berry', '오랭열매', 'medicine', 10, '포켓몬에게 지니게 하면 HP를 10만큼 회복한다.', 'Held: Consumed at 1/2 max HP to recover 10 HP.'),
    (133, 'persim-berry', '시몬열매', 'medicine', 10, '포켓몬에게 지니게 하면 혼란을 회복한다.', 'Held: Consumed when confused to cure confusion.'),
    (134, 'lum-berry', '리샘열매', 'medicine', 10, '포켓몬에게 지니게 하면 모든 상태 이상을 회복한다.', 'Held: Consumed to cure any status condition or confusion.'),
    (135, 'sitrus-berry', '자뭉열매', 'medicine', 10, '포켓몬에게 지니게 하면 HP를 조금 회복한다.', 'Held: Consumed at 1/2 max HP to recover 1/4 max HP.'),
    (161, 'occa-berry', '오카열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 불꽃 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Fire-type attack to halve the damage.'),
    (162, 'passho-berry', '꼬시개열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 물 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Water-type attack to halve the damage.'),
    (163, 'wacan-berry', '초나열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 전기 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Electric-type attack to halve the damage.'),
    (164, 'rindo-berry', '린드열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 풀 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Grass-type attack to halve the damage.'),
    (165, 'yache-berry', '플카열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 얼음 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Ice-type attack to halve the damage.'),
    (166, 'chople-berry', '로플열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 격투 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Fighting-type attack to halve the damage.'),
    (167, 'kebia-berry', '으름열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 독 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Poison-type attack to halve the damage.'),
    (168, 'shuca-berry', '슈캐열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 땅 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Ground-type attack to halve the damage.'),
    (169, 'coba-berry', '바코열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 비행 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Flying-type attack to halve the damage.'),
    (170, 'payapa-berry', '야파열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 에스퍼 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Psychic-type attack to halve the damage.'),
    (171, 'tanga-berry', '리체열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 벌레 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Bug-type attack to halve the damage.'),
    (172, 'charti-berry', '루미열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 바위 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Rock-type attack to halve the damage.'),
    (173, 'kasib-berry', '수불열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 고스트 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Ghost-type attack to halve the damage.'),
    (174, 'haban-berry', '하반열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 드래곤 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Dragon-type attack to halve the damage.'),
    (175, 'colbur-berry', '마코열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 악 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Dark-type attack to halve the damage.'),
    (176, 'babiri-berry', '바리비열매', 'type-protection', 10, '포켓몬에게 지니게 하면 효과가 뛰어난 강철 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a super-effective Steel-type attack to halve the damage.'),
    (177, 'chilan-berry', '카리열매', 'type-protection', 10, '포켓몬에게 지니게 하면 노말 기술을 당했을 때 위력이 약해진다.', 'Held: Consumed when struck by a Normal-type attack to halve the damage.'),
    (190, 'bright-powder', '반짝가루', 'held-items', 10, '반짝반짝 빛나는 가루. 지니게 하면 빛이 상대를 혼란시켜 기술이 명중되기 어려워진다.', 'Held: Increases the holder’s evasion by 1/9 (11 1/9%).'),
    (191, 'white-herb', '하양허브', 'held-items', 10, '지니게 한 포켓몬의 능력이 떨어졌을 때 한 번만 원래 상태로 돌아온다.', 'Held: Resets all lowered stats to normal at end of turn. Consumed after use.'),
    (194, 'quick-claw', '선제공격손톱', 'held-items', 80, '가볍고 날카로운 손톱. 지니게 하면 상대보다 먼저 행동할 수도 있다.', 'Held: Holder has a 3/16 (18.75%) chance to move first.'),
    (196, 'mental-herb', '멘탈허브', 'held-items', 10, '지니게 한 포켓몬은 헤롱헤롱 상태가 되었을 때 한 번만 회복한다.', 'Held: Consumed to cure infatuation. Gen V: Also removes Taunt, Encore, Torment, Disable, and Cursed Body.'),
    (197, 'choice-band', '구애머리띠', 'choice', 10, '기술을 구애받는 머리띠. 지니게 하면 공격은 올라가지만 똑같은 기술밖에 쓰지 못한다.', 'Held: Increases Attack by 50%, but restricts the holder to only one move.'),
    (198, 'kings-rock', '왕의징표석', 'held-items', 30, '지니게 하면 공격해서 데미지를 줄 때 상대를 풀죽이기도 한다.', 'Held: Damaging moves gain a 10% chance to make their target flinch. Traded on a Poliwhirl: Holder evolves into Politoed. Traded on a Slowpoke: Holder evolves into Slowking.'),
    (199, 'silver-powder', '은빛가루', 'type-enhancement', 10, '은색으로 반짝이는 가루. 지니게 하면 벌레타입 기술의 위력이 올라간다.', 'Held: Bug-Type moves from holder do 20% more damage.'),
    (207, 'focus-band', '기합의머리띠', 'held-items', 10, '지니게 하면 기절할 듯한 기술을 받아도 HP를 1 남겨서 견디기도 한다.', 'Held: Holder has 10% chance to survive attacks or self-inflicted damage at 1 HP.'),
    (209, 'scope-lens', '초점렌즈', 'held-items', 30, '약점이 보이는 렌즈. 지니게 한 포켓몬의 기술이 급소에 맞기 쉬워진다.', 'Held: Raises the holder’s critical hit ratio by one stage.'),
    (210, 'metal-coat', '금속코트', 'type-enhancement', 30, '특수한 금속 장막. 지니게 하면 강철타입 기술의 위력이 올라간다.', 'Held: Steel-Type moves from holder do 20% more damage.'),
    (211, 'leftovers', '먹다남은음식', 'held-items', 10, '지니게 하면 포켓몬의 HP가 배틀을 하는 동안 조금씩 회복된다.', 'Held: Restores 1/16 (6.25%) holder’s max HP at the end of each turn.'),
    (213, 'light-ball', '전기구슬', 'species-specific', 30, '피카츄에게 지니게 하면 공격과 특수공격의 위력이 올라가는 이상한 구슬.', 'Doubles Pikachu’s Attack and Special Attack. Breed on Pikachu or Raichu: Pichu Egg will have Volt Tackle.'),
    (214, 'soft-sand', '부드러운모래', 'type-enhancement', 10, '만지면 보슬보슬한 모래. 지니게 하면 땅타입 기술의 위력이 올라간다.', 'Held: Ground-Type moves from holder do 20% more damage.'),
    (215, 'hard-stone', '딱딱한돌', 'type-enhancement', 100, '절대 깨지지 않는 돌. 지니게 하면 바위타입 기술의 위력이 올라간다.', 'Held: Rock-Type moves from holder do 20% more damage.'),
    (216, 'miracle-seed', '기적의씨', 'type-enhancement', 30, '생명이 깃든 씨앗. 지니게 하면 풀타입 기술의 위력이 올라간다.', 'Held: Grass-Type moves from holder do 20% more damage.'),
    (217, 'black-glasses', '검은안경', 'type-enhancement', 30, '괴상하게 보이는 안경. 지니게 하면 악타입 기술의 위력이 올라간다.', 'Held: Dark-Type moves from holder do 20% more damage.'),
    (218, 'black-belt', '검은띠', 'type-enhancement', 30, '마음을 긴장시키는 띠. 지니게 하면 격투타입 기술의 위력이 올라간다.', 'Held: Fighting-Type moves from holder do 20% more damage.'),
    (219, 'magnet', '자석', 'type-enhancement', 30, '강력한 자석. 지니게 하면 전기타입 기술의 위력이 올라간다.', 'Held: Electric-Type moves from holder do 20% more damage.'),
    (220, 'mystic-water', '신비의물방울', 'type-enhancement', 30, '물방울 모양의 보석. 지니게 하면 물타입 기술의 위력이 올라간다.', 'Held: Water-Type moves from holder do 20% more damage.'),
    (221, 'sharp-beak', '예리한부리', 'type-enhancement', 50, '길고 뾰족한 부리. 지니게 하면 비행타입 기술의 위력이 올라간다.', 'Held: Flying-Type moves from holder do 20% more damage.'),
    (222, 'poison-barb', '독바늘', 'type-enhancement', 70, '독이 있는 작은 침. 지니게 하면 독타입 기술의 위력이 올라간다.', 'Held: Poison-Type moves from holder do 20% more damage.'),
    (223, 'never-melt-ice', '녹지않는얼음', 'type-enhancement', 30, '열을 가까이하지 않게 하는 얼음. 지니게 하면 얼음타입 기술의 위력이 올라간다.', 'Held: Ice-Type moves from holder do 20% more damage.'),
    (224, 'spell-tag', '저주의부적', 'type-enhancement', 30, '괴상하고 으스스한 부적. 지니게 하면 고스트타입 기술의 위력이 올라간다.', 'Held: Ghost-Type moves from holder do 20% more damage.'),
    (225, 'twisted-spoon', '휘어진스푼', 'type-enhancement', 30, '염동력을 담은 숟가락. 지니게 하면 에스퍼타입 기술의 위력이 올라간다.', 'Held: Psychic-Type moves from holder do 20% more damage.'),
    (226, 'charcoal', '목탄', 'type-enhancement', 30, '물건을 태우는 연료. 지니게 하면 불꽃타입 기술의 위력이 올라간다.', 'Held: Fire-Type moves from holder do 20% more damage.'),
    (227, 'dragon-fang', '용의이빨', 'type-enhancement', 70, '단단하고 날카로운 이빨. 지니게 하면 드래곤타입 기술의 위력이 올라간다.', 'Held: Dragon-Type moves from holder do 20% more damage.'),
    (228, 'silk-scarf', '실크스카프', 'type-enhancement', 10, '감촉이 좋은 스카프. 지니게 하면 노말타입 기술의 위력이 올라간다.', 'Held: Normal-Type moves from holder do 20% more damage.'),
    (230, 'shell-bell', '조개껍질방울', 'held-items', 30, '지니게 한 포켓몬이 공격하여 상대에게 데미지를 줬을 때 HP를 조금 회복할 수 있다.', 'Held: Holder receives 1/8 of the damage it deals when attacking.'),
    (242, 'wide-lens', '광각렌즈', 'held-items', 10, '물건이 크게 보이는 렌즈. 지니게 하면 기술의 명중률이 조금 올라간다.', 'Held: Provides a 1/10 (10%) boost in accuracy to the holder.'),
    (243, 'muscle-band', '힘의머리띠', 'held-items', 10, '힘이 끓어오르는 머리띠. 지니게 하면 물리 기술의 위력이 조금 올라간다.', 'Held: Boosts the damage of physical moves used by the holder by 10%.'),
    (244, 'wise-glasses', '박식안경', 'held-items', 10, '두꺼운 렌즈를 붙인 안경. 지니게 하면 특수 기술의 위력이 조금 올라간다.', 'Held: Boosts the damage of special moves used by the holder by 1/10 (10%).'),
    (245, 'expert-belt', '달인의띠', 'held-items', 10, '오래 사용한 까만 띠. 지니게 하면 효과가 뛰어날 때 기술의 위력이 조금 올라간다.', 'Held: Holder’s Super Effective moves do 20% extra damage.'),
    (246, 'light-clay', '빛의점토', 'held-items', 30, '지니게 한 포켓몬이 빛의장막이나 리플렉터를 사용했을 때 여느 때보다 긴 시간 동안 지속된다.', 'Held: Light Screen and Reflect used by the holder last 8 rounds instead of 5.'),
    (247, 'life-orb', '생명의구슬', 'held-items', 30, '지니게 하면 공격할 때마다 HP가 조금씩 줄지만 기술의 위력이 올라간다.', 'Held: Holder’s moves inflict 30% extra damage, but cost 10% max HP.'),
    (248, 'power-herb', '파워풀허브', 'held-items', 10, '지니게 한 포켓몬은 한 번만 1턴째에 힘을 모으는 기술을 바로 사용할 수가 있다.', 'Held: Both turns of a two-turn charge move happen at once. Consumed upon use.'),
    (252, 'focus-sash', '기합의띠', 'held-items', 10, '지니게 하면 HP가 꽉 찼을 때 기절할 듯한 기술을 당해도 HP 1로 한 번은 버틴다.', 'Held: Holder survives any single-hit attack at 1 HP if at max HP, then the item is consumed.'),
    (253, 'zoom-lens', '포커스렌즈', 'held-items', 10, '지니게 한 포켓몬이 상대보다도 행동하는 것이 늦을 때 기술이 명중하기 쉬워진다.', 'Held: Provides a 1/5 (20%) boost in accuracy if the holder moves after the target.'),
    (254, 'metronome', '메트로놈', 'held-items', 30, '지니게 하면 똑같은 기술을 연속으로 사용했을 때 위력이 올라간다. 그만두면 위력이 되돌아간다.', 'Held: Consectutive uses of the same attack have a cumulative damage boost of 10%. Maximum 100% boost.'),
    (255, 'iron-ball', '검은철구', 'bad-held-items', 130, '지니게 하면 스피드가 떨어진다. 비행타입이나 부유포켓몬은 땅 기술에 맞아 버린다.', 'Held: Holder’s Speed is halved. Negates all Ground-type immunities, and makes Flying-types take neutral damage from Ground-type moves. Arena Trap. Spikes, and Toxic Spikes affect the holder.'),
    (259, 'icy-rock', '차가운바위', 'held-items', 40, '지니게 한 포켓몬이 싸라기눈을 쓰면 여느 때보다 싸라기눈의 시간이 길어진다.', 'Held: Hail by the holder lasts 8 rounds instead of 5.'),
    (260, 'smooth-rock', '보송보송바위', 'held-items', 10, '지니게 한 포켓몬이 모래바람을 쓰면 여느 때보다 모래바람의 시간이 길어진다.', 'Held: Sandstorm by the holder lasts 8 rounds instead of 5.'),
    (261, 'heat-rock', '뜨거운바위', 'held-items', 60, '지니게 한 포켓몬이 쾌청을 쓰면 여느 때보다 쾌청의 시간이 길어진다.', 'Held: Sunny Day by the holder lasts 8 rounds instead of 5.'),
    (262, 'damp-rock', '축축한바위', 'held-items', 60, '지니게 한 포켓몬이 비바라기를 쓰면 여느 때보다 비 내리는 시간이 길어진다.', 'Held: Rain Dance by the holder lasts 8 rounds instead of 5.'),
    (264, 'choice-scarf', '구애스카프', 'choice', 10, '기술을 구애받는 스카프. 지니게 하면 스피드는 올라가지만 같은 기술밖에 쓸 수 없다.', 'Held: Increases Speed by 50%, but restricts the holder to only one move.'),
    (272, 'shed-shell', '아름다운허물', 'held-items', 10, '튼튼하고 단단한 허물. 지니게 한 포켓몬은 교대 포켓몬과 반드시 교체할 수 있다.', 'Held: Holder can bypass all trapping effects and switch out. Multi-turn moves still cannot be switched out of.'),
    (273, 'big-root', '큰뿌리', 'held-items', 10, '지니게 하면 HP 흡수 기술을 썼을 때 여느 때보다 많은 HP를 자신이 회복할 수 있다.', 'Held: Increases HP recovered from draining moves, Ingrain, and Aqua Ring by 3/10 (30%).'),
    (274, 'choice-specs', '구애안경', 'choice', 10, '기술을 구애받는 안경. 지니게 하면 특수공격이 올라가지만 같은 기술밖에 쓸 수 없다.', 'Held: Increases Special Attack by 50%, but restricts the holder to only one move.'),
    (695, 'gengarite', '팬텀나이트', 'mega-stones', 80, '팬텀에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Gengar to Mega Evolve into Mega Gengar.'),
    (696, 'gardevoirite', '가디안나이트', 'mega-stones', 80, '가디안에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Gardevoir to Mega Evolve into Mega Gardevoir.'),
    (697, 'ampharosite', '전룡나이트', 'mega-stones', 80, '전룡에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Ampharos to Mega Evolve into Mega Ampharos.'),
    (698, 'venusaurite', '이상해꽃나이트', 'mega-stones', 80, '이상해꽃에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Venusaur to Mega Evolve into Mega Venusaur.'),
    (699, 'charizardite-x', '리자몽나이트X', 'mega-stones', 80, '리자몽에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Charizard to Mega Evolve into Mega Charizard X.'),
    (700, 'blastoisinite', '거북왕나이트', 'mega-stones', 80, '거북왕에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Blastoise to Mega Evolve into Mega Blastoise.'),
    (701, 'mewtwonite-x', '뮤츠나이트X', 'mega-stones', 80, '뮤츠에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Mewtwo to Mega Evolve into Mega Mewtwo X.'),
    (702, 'mewtwonite-y', '뮤츠나이트Y', 'mega-stones', 80, '뮤츠에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Mewtwo to Mega Evolve into Mega Mewtwo Y.'),
    (703, 'blazikenite', '번치코나이트', 'mega-stones', 80, '번치코에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Blaziken to Mega Evolve into Mega Blaziken.'),
    (704, 'medichamite', '요가램나이트', 'mega-stones', 80, '요가램에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.', 'Held: Allows Medicham to Mega Evolve into Mega Medicham.'),
